/** All translations for zizhitongjian ch.164 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第164卷卷第一百六十四", literal: "Comprehensive Mirror in Aid of Governance, Volume 164, Roll 164", idiomatic: "Comprehensive Mirror in Aid of Governance, Volume 164" },
  { zh: "【梁紀二十】　起重光協洽，盡玄黓涒灘，凡二年。", literal: "[Liang Records 20] From Chongguang Xieqia through Xuanyi Youtan; two years in all.", idiomatic: "[Liang Records 20] From Chongguang Xieqia through Xuanyi Youtan—two years in all." },
  { zh: "太宗簡文皇帝下大寶二年（", literal: "Great Ancestor Emperor Jianwen, lower scroll, second year of Dabao (", idiomatic: "Emperor Jianwen of Liang, second year of Dabao (" },
  { zh: "辛未，公元五五一年）", literal: "xinwei, 551 CE)", idiomatic: "xinwei, AD 551)" },
  { zh: "春，正月，新吳余孝頃舉兵拒侯景，景遣于慶攻之，不克。", literal: "In spring, the first month, Yu Xiaoqing of Xinwu raised troops to resist Hou Jing; Jing sent Yu Qing to attack him and could not overcome him.", idiomatic: "In spring, the first month, Yu Xiaoqing of Xinwu raised troops against Hou Jing. Jing sent Yu Qing to attack him but failed to break him." },
  { zh: "庚戌，湘東王繹遣護軍將軍尹悅、安東將軍杜幼安、巴州刺史王珣將兵二萬自江夏趣武昌，受徐文盛節度。", literal: "On gengxu, Prince of Xiangdong Yi sent Guard-General Yin Yue, Pacification-East General Du You'an, and Bazhou Inspector Wang Xun with twenty thousand men from Jiangxia toward Wuchang, under Xu Wensheng's command.", idiomatic: "On gengxu, Prince Xiao Yi of Xiangdong sent guard-general Yin Yue, pacification-east general Du You'an, and Bazhou inspector Wang Xun with twenty thousand men from Jiangxia toward Wuchang, under Xu Wensheng's command." },
  { zh: "楊乾運攻拔劍閣，楊法琛退保石門，乾運據南陰平。", literal: "Yang Qianyun stormed and took Jiange; Yang Fachen withdrew to hold Shimen; Qianyun seized Southern Yinping.", idiomatic: "Yang Qianyun stormed and took Jiange. Yang Fachen withdrew to Shimen while Qianyun seized Southern Yinping." },
  { zh: "辛亥，齊主祀圜丘。", literal: "On xinhai, the Qi ruler sacrificed at the Round Mound.", idiomatic: "On xinhai, the Qi emperor sacrificed at the Round Mound." },
  { zh: "張彪遣其將趙稜圍錢塘，孫鳳圍富春，侯景遣儀同三司田遷、趙伯超救之，稜、鳳敗走。", literal: "Zhang Biao sent his generals Zhao Ling to besiege Qiantang and Sun Feng to besiege Fuchun; Hou Jing sent Masters of Protocol Tian Qian and Zhao Bochao to rescue them; Ling and Feng were defeated and fled.", idiomatic: "Zhang Biao sent Zhao Ling to besiege Qiantang and Sun Feng to besiege Fuchun. Hou Jing sent masters of protocol Tian Qian and Zhao Bochao to relieve them. Ling and Feng were routed and fled." },
  { zh: "稜，伯超之兄子也。", literal: "Ling was Bochao's elder brother's son.", idiomatic: "Ling was the son of Bochao's elder brother." },
  { zh: "癸亥，齊主耕籍田。", literal: "On guihai, the Qi ruler plowed the sacred field.", idiomatic: "On guihai, the Qi emperor plowed the sacred field." },
  { zh: "乙丑，享太廟。", literal: "On yichou, he offered at the Imperial Ancestral Temple.", idiomatic: "On yichou, he offered at the Imperial Ancestral Temple." },
  { zh: "魏楊忠圍汝南，李素戰死。", literal: "Wei Yang Zhong besieged Runan; Li Su died in battle.", idiomatic: "Yang Zhong of Wei besieged Runan; Li Su fell in battle." },
  { zh: "二月，乙亥，城陷，執邵陵攜王綸，殺之，投屍江岸；", literal: "In the second month, on yihai, the city fell; they seized Prince of Shaoling Lun, the hostage prince, killed him, and cast his corpse on the riverbank;", idiomatic: "In the second month, on yihai, the city fell. They seized Prince Lun of Shaoling, the hostage prince, killed him, and cast his body on the riverbank;" },
  { zh: "岳陽王察取而葬之。", literal: "Prince of Yueyang Cha took it and buried him.", idiomatic: "Prince Cha of Yueyang recovered the body and buried him." },
  { zh: "或告齊太尉彭樂謀反；", literal: "Someone reported that Qi Grand Commandant Peng Yue plotted rebellion;", idiomatic: "Someone reported that Qi grand commandant Peng Yue was plotting rebellion;" },
  { zh: "壬辰，樂坐誅。", literal: "on renchen, Yue was executed for his crime.", idiomatic: "on renchen, Yue was executed." },
  { zh: "齊遣散騎常侍曹文皎使於江陵，湘東王繹使兼散騎常侍王子敏報之。", literal: "Qi sent Palace Attendant Cao Wenjiao as envoy to Jiangling; Prince of Xiangdong Yi sent Concurrent Palace Attendant Wang Zimin in reply.", idiomatic: "Qi sent palace attendant Cao Wenjiao to Jiangling; Prince Xiao Yi of Xiangdong sent concurrent palace attendant Wang Zimin in reply." },
  { zh: "侯景以王克為太師，宋子仙為太保，元羅為太傅，郭元建為太尉，支化仁為司徒，任約為司空，王偉為尚書左僕射，索超世為右僕射。", literal: "Hou Jing made Wang Ke Grand Preceptor, Song Zixian Grand Guardian, Yuan Luo Grand Tutor, Guo Yuanjian Grand Commandant, Zhi Huaren Minister of Education, Ren Yue Minister of Works, Wang Wei Left Vice Director of the Masters of Writing, and Suo Chaoshi Right Vice Director.", idiomatic: "Hou Jing made Wang Ke grand preceptor, Song Zixian grand guardian, Yuan Luo grand tutor, Guo Yuanjian grand commandant, Zhi Huaren minister of education, Ren Yue minister of works, Wang Wei left vice director of the masters of writing, and Suo Chaoshi right vice director." },
  { zh: "景置三公官，動以十數，儀同尤多。", literal: "Jing established the Three Dukes' offices by the tens, and Masters of Protocol were especially numerous.", idiomatic: "Jing created Three Dukes' posts by the dozen, and masters of protocol were especially thick on the ground." },
  { zh: "以子仙、元建、化仁為佐命元功，偉、超世為謀主，於子悅、彭雋主擊斷，陳慶、呂季略、盧暉略、丁和等為爪牙。", literal: "He took Zixian, Yuanjian, and Huaren as founding merit of co-rule, Wei and Chaoshi as chief strategists, Yu Ziyue and Peng Juan as masters of judgment, and Chen Qing, Lü Jilüe, Lu Huilüe, Ding He, and others as claws and fangs.", idiomatic: "Zixian, Yuanjian, and Huaren were his founding merit; Wei and Chaoshi were chief strategists; Yu Ziyue and Peng Juan held judgment; Chen Qing, Lü Jilüe, Lu Huilüe, Ding He, and others were his claws and fangs." },
  { zh: "梁人為景用者，則故將軍趙伯超，前制局監周石珍，內監嚴但，邵陵王記室伏知命。", literal: "Liang men Jing employed were former general Zhao Bochao, former Bureau of Manufactures supervisor Zhou Shizhen, inner attendant Yan Dan, and Prince of Shaoling's recorder Fu Zhiming.", idiomatic: "Among Liang men in Jing's service were former general Zhao Bochao, former bureau of manufactures supervisor Zhou Shizhen, inner attendant Yan Dan, and Prince Lun of Shaoling's recorder Fu Zhiming." },
  { zh: "自餘王克、元羅及侍中殷不害、太常周弘正等，景從人望，加以尊位，非腹心之任也。", literal: "As for the rest—Wang Ke, Yuan Luo, Palace Attendant Yin Buhai, Chamberlain for Ceremonials Zhou Hongzheng, and the like—Jing followed men's repute and gave them honored posts, but they were not trusted inner duties.", idiomatic: "As for the rest—Wang Ke, Yuan Luo, palace attendant Yin Buhai, chamberlain for ceremonials Zhou Hongzheng, and the like—Jing followed public esteem and gave them honored posts, but they were not trusted inner duties." },
  { zh: "北兗州刺史蕭邕謀降魏，侯景殺之。", literal: "Northern Yanzhou Inspector Xiao Yong plotted to surrender to Wei; Hou Jing killed him.", idiomatic: "Northern Yanzhou inspector Xiao Yong plotted to surrender to Wei; Hou Jing killed him." },
  { zh: "楊乾運進據平興，平興者，楊法琛所治也。", literal: "Yang Qianyun advanced and seized Pingxing; Pingxing was what Yang Fachen governed.", idiomatic: "Yang Qianyun advanced and seized Pingxing, which Yang Fachen had governed." },
  { zh: "法琛退保魚石洞，乾運焚平興而歸。", literal: "Fachen withdrew to hold Yushi Cave; Qianyun burned Pingxing and returned.", idiomatic: "Fachen withdrew to Yushi Cave; Qianyun burned Pingxing and withdrew." },
  { zh: "李遷仕收眾還擊南康，陳霸先遣其將杜僧明等拒之，生擒遷仕，斬之。", literal: "Li Qianshi gathered his followers and returned to strike Nankang; Chen Baxian sent his generals Du Sengming and others to resist, captured Qianshi alive, and beheaded him.", idiomatic: "Li Qianshi gathered his men and struck at Nankang. Chen Baxian sent Du Sengming and others against him, took Qianshi alive, and beheaded him." },
  { zh: "湘東王繹使霸先進兵取江州，以為江州刺史。", literal: "Prince of Xiangdong Yi had Baxian advance to take Jiang province and made him Jiangzhou Inspector.", idiomatic: "Prince Xiao Yi of Xiangdong had Baxian advance to take Jiang province and made him Jiangzhou inspector." },
  { zh: "三月，丙午，齊襄城王淯卒。", literal: "In the third month, on bingwu, Prince of Xiangcheng You died.", idiomatic: "In the third month, on bingwu, Prince You of Xiangcheng died." },
  { zh: "庚戌，魏文帝殂，太子欽立。", literal: "On gengxu, Wei Emperor Wen died; the crown prince Qin succeeded.", idiomatic: "On gengxu, Emperor Wen of Wei died; crown prince Qin succeeded." },
  { zh: "乙卯，徐文盛等克武昌，進軍蘆洲。", literal: "On yimao, Xu Wensheng and others took Wuchang and advanced to Luzhou.", idiomatic: "On yimao, Xu Wensheng and others took Wuchang and advanced to Luzhou." },
  { zh: "己未，齊以湘東王繹為梁相國，建梁台，總百揆，承製。", literal: "On jiwei, Qi made Prince of Xiangdong Yi Liang's Chancellor of State, raised the Liang headquarters, oversaw the hundred duties, and acted by regent's order.", idiomatic: "On jiwei, Qi made Prince Xiao Yi of Xiangdong chancellor of state for Liang, raised the Liang headquarters, oversaw the hundred duties, and acted by regent's order." },
  { zh: "齊司空司馬子如自求封王，齊主怒，庚申，免子如官。", literal: "Qi Minister of Works Sima Ziru asked to be enfeoffed as prince; the Qi ruler was angry; on gengshen he removed Ziru from office.", idiomatic: "Qi minister of works Sima Ziru asked to be enfeoffed as prince. The Qi emperor was furious; on gengshen he stripped Ziru of office." },
  { zh: "任約告急，侯景自帥眾西上，攜太子大器從軍以為質，留王偉居守。", literal: "Ren Yue reported in emergency; Hou Jing himself led troops west, taking crown prince Daqi with the army as hostage, and left Wang Wei to hold the capital.", idiomatic: "Ren Yue called for help. Hou Jing himself led troops west, taking crown prince Daqi with the army as hostage, and left Wang Wei to hold the capital." },
  { zh: "閏月，景發建康，自石頭至新林，舳艫相接。", literal: "In the intercalary month, Jing set out from Jiankang; from Shitou to Xinlin, ships and boats linked stem to stern.", idiomatic: "In the intercalary month, Jing marched from Jiankang. From Shitou to Xinlin, ships lay stem to stern." },
  { zh: "約分兵襲破定州刺史田龍祖於齊安。", literal: "Yue detached troops and in a raid broke Dingzhou Inspector Tian Longzu at Qi'an.", idiomatic: "Yue detached troops and routed Dingzhou inspector Tian Longzu at Qi'an." },
  { zh: "壬寅，景軍至西陽，與徐文盛夾江築壘。", literal: "On renyin, Jing's army reached Xiyang and built ramparts on both banks of the river facing Xu Wensheng.", idiomatic: "On renyin, Jing's army reached Xiyang and built ramparts on both banks facing Xu Wensheng." },
  { zh: "癸卯，文盛擊破之，射其右丞庫狄式和墜水死，景遁走還營。", literal: "On guimao, Wensheng struck and broke them, shot his right aide Kudi Shihe so that he fell into the water and died; Jing fled back to camp.", idiomatic: "On guimao, Wensheng routed them, shot his right aide Kudi Shihe into the river to his death; Jing fled back to camp." },
  { zh: "夏，四月，甲辰，魏葬文帝於永陵。", literal: "In summer, the fourth month, on jiachen, Wei buried Emperor Wen at Yongling.", idiomatic: "In summer, the fourth month, on jiachen, Wei buried Emperor Wen at Yongling." },
  { zh: "郢州刺史蕭方諸，年十五，以行事鮑泉和弱，常侮易之，或使伏床，騎背為馬；", literal: "Yingzhou Inspector Xiao Fangzhu, fifteen years old, because acting administrator Bao Quan was mild and weak, often insulted and belittled him, sometimes made him lie face down on a bed and rode his back as a horse;", idiomatic: "Yingzhou inspector Xiao Fangzhu was fifteen. Because acting administrator Bao Quan was mild and weak, he often bullied him, sometimes made him lie on a bed, and rode his back as a horse;" },
  { zh: "恃徐文盛軍在近，不復設備，日以蒲酒為樂。", literal: "relying on Xu Wensheng's army being near, he no longer made preparations and passed his days in reed-wine pleasure.", idiomatic: "trusting that Xu Wensheng's army was near, he stopped preparing defenses and spent his days in reed-wine pleasure." },
  { zh: "侯景聞江夏空虛，乙巳，使宋子仙、任約帥精騎四百，由淮內襲郢州。", literal: "Hou Jing heard Jiangxia was empty; on yisi he sent Song Zixian and Ren Yue leading four hundred picked horsemen through the Huai interior to strike Ying province.", idiomatic: "Hou Jing heard Jiangxia was undefended. On yisi he sent Song Zixian and Ren Yue with four hundred picked horsemen through the Huai interior to strike Ying province." },
  { zh: "丙午，大風疾雨，天色晦冥，有登陴望見賊者，告泉曰：「虜騎至矣！", literal: "On bingwu, great wind and driving rain; the sky was dark; someone who climbed the wall and saw the enemy reported to Quan: \"The barbarian horsemen have come!", idiomatic: "On bingwu came great wind and driving rain; the sky went black. Someone who climbed the wall and saw the enemy told Quan: \"The enemy horsemen are here!" },
  { zh: "」泉曰：「徐文盛大軍在下，賊何因得至！", literal: "\" Quan said: \"Xu Wensheng's great army is downstream—how could the enemy get here!", idiomatic: "\" Quan said: \"Xu Wensheng's main force is downstream—how could the enemy get here!" },
  { zh: "當是王珣軍人還耳。", literal: "It must be Wang Xun's troops returning.", idiomatic: "It must be Wang Xun's men returning." },
  { zh: "」既而走告者稍眾，始命閉門，子仙等已入城。", literal: "\" Before long those who came running to report grew numerous; only then did he order the gates closed—but Zixian and the others were already inside the city.", idiomatic: "\" Before long more runners came; only then did he order the gates shut—but Zixian and the others were already inside." },
  { zh: "方諸方踞泉腹，以五色彩辮其髯；", literal: "Fangzhu was just sitting astride Quan's belly, braiding his beard with five-colored threads;", idiomatic: "Fangzhu was sitting astride Quan's belly, braiding his beard with five-colored thread;" },
  { zh: "見子仙至，方諸迎拜，泉匿於床下；", literal: "when he saw Zixian arrive, Fangzhu rose to bow in welcome; Quan hid under the bed;", idiomatic: "when Zixian arrived, Fangzhu rose to bow; Quan hid under the bed;" },
  { zh: "子仙俯窺見泉素髯間彩，驚愕，遂擒之，及司馬虞豫，送於景所。", literal: "Zixian bent down, peered in, saw Quan's plain beard threaded with color, was startled, seized him, and also Chief Clerk Yu Yu, and sent them to Jing's camp.", idiomatic: "Zixian bent down, saw Quan's plain beard threaded with color, seized him in shock, and also chief clerk Yu Yu, and sent both to Jing." },
  { zh: "景因便風，中江舉帆，遂越文盛等軍。", literal: "Jing caught a favorable wind, raised sail mid-river, and thus passed ahead of Wensheng's army and the rest.", idiomatic: "Jing caught a fair wind, raised sail mid-river, and swept past Wensheng's army." },
  { zh: "丁未，入江夏。", literal: "On dingwei, he entered Jiangxia.", idiomatic: "On dingwei, he entered Jiangxia." },
  { zh: "文盛眾懼而潰，與長沙王韶等逃歸江陵。", literal: "Wensheng's troops feared and broke; with Prince of Changsha Shao and others he fled back to Jiangling.", idiomatic: "Wensheng's men panicked and broke. With Prince Shao of Changsha and others he fled to Jiangling." },
  { zh: "珣、杜幼安以家在江夏，遂降於景。", literal: "Xun and Du You'an, because their families were in Jiangxia, then surrendered to Jing.", idiomatic: "Xun and Du You'an, whose families were in Jiangxia, surrendered to Jing." },
  { zh: "湘東王繹以王僧辯為大都督，帥巴州刺史丹楊淳於量、定州刺史杜龕、宜州刺史王琳、郴州刺史裴之橫東擊景，徐文盛以下並受節度。", literal: "Prince of Xiangdong Yi made Wang Senbian Grand Commander, leading Bazhou Inspector Chunyu Liang of Danyang, Dingzhou Inspector Du Kan, Yizhou Inspector Wang Lin, and Chenzhou Inspector Pei Zhiheng east to strike Jing; Xu Wensheng and those below all accepted his command.", idiomatic: "Prince Xiao Yi of Xiangdong made Wang Senbian grand commander, leading Bazhou inspector Chunyu Liang of Danyang, Dingzhou inspector Du Kan, Yizhou inspector Wang Lin, and Chenzhou inspector Pei Zhiheng east against Jing; Xu Wensheng and all below accepted his command." },
  { zh: "戊申，僧辯等軍至巴陵，聞郢州已陷，因留戍之。", literal: "On wushen, Senbian's army and the rest reached Baling; hearing Ying province had fallen, they therefore remained to garrison it.", idiomatic: "On wushen, Senbian reached Baling. Hearing Ying province had fallen, he halted to garrison it." },
  { zh: "繹遺僧辯書曰：「賊既乘勝，必將西下，不勞遠擊；", literal: "Yi sent Senbian a letter saying: \"The rebels, having ridden victory, are sure to come west downstream—no need for a distant strike;", idiomatic: "Yi wrote Senbian: \"The rebels, riding victory, are sure to come west—no need to chase them far;" },
  { zh: "但守巴丘，以逸待勞，無慮不克。", literal: "only hold Baling, meet weariness with rest, and there is no worry of failure.", idiomatic: "only hold Baling, meet their weariness with your rest, and you cannot fail." },
  { zh: "」又謂僚佐曰：「景若水步兩道，直指江陵，此上策也；", literal: "\" He also told his staff: \"If Jing takes both water and land routes straight at Jiangling, that is the upper plan;", idiomatic: "\" He also told his staff: \"If Jing takes both river and land straight at Jiangling, that is the best plan;" },
  { zh: "據夏首，積兵糧，中策也；", literal: "to hold Xiakou and stock troops and grain is the middle plan;", idiomatic: "to hold Xiakou and stock troops and grain is the middle plan;" },
  { zh: "悉力攻巴陵，下策也。", literal: "to throw all strength at Baling is the lower plan.", idiomatic: "to throw everything at Baling is the worst plan." },
  { zh: "巴陵城小而固，僧辯足可委任。", literal: "Baling's walls are small but firm; Senbian is fully fit to be entrusted.", idiomatic: "Baling is small but strong; Senbian is fully fit to hold it." },
  { zh: "景攻城不拔，野無所掠，暑疫時起，食盡兵疲，破之必矣。", literal: "If Jing besieges and cannot take it, the countryside offers nothing to plunder, summer pestilence rises in season, food runs out and troops weary—breaking him is certain.", idiomatic: "If Jing cannot take it, the countryside offers nothing to plunder, summer pestilence will rise, food will run out and his men will weary—then he is finished." },
  { zh: "」乃命羅州刺史徐嗣徽自岳陽、武州刺史杜崱自武陵引兵會僧辯。", literal: "\" He then ordered Luozhou Inspector Xu Sihui from Yueyang and Wuzhou Inspector Du Xi from Wuling to lead troops and join Senbian.", idiomatic: "\" He ordered Luozhou inspector Xu Sihui from Yueyang and Wuzhou inspector Du Xi from Wuling to bring troops and join Senbian." },
  { zh: "景使丁和將兵五千守夏首，宋子仙將兵一萬為前驅，趣巴陵，分遣任約直指江陵，景帥大兵水步繼進。", literal: "Jing sent Ding He with five thousand men to hold Xiakou, Song Zixian with ten thousand as vanguard hurrying to Baling, detached Ren Yue straight at Jiangling, and Jing himself led the main force by water and land in succession.", idiomatic: "Jing sent Ding He with five thousand to hold Xiakou and Song Zixian with ten thousand as vanguard for Baling, detached Ren Yue straight at Jiangling, and followed with the main force by river and road." },
  { zh: "於是緣江戍邏，望風請服，景拓邏至於隱磯。", literal: "Thus along the river the garrison posts, seeing the wind, asked to submit; Jing extended his patrols to Yinjii.", idiomatic: "Along the river the garrisons submitted at the first rumor; Jing extended his patrols to Yinjii." },
  { zh: "僧辯乘城固守，偃旗臥鼓，安若無人。", literal: "Senbian manned the walls and held firm, lowered banners and stilled drums, calm as if no one were there.", idiomatic: "Senbian held the walls, lowered banners and stilled drums, calm as if the city were empty." },
  { zh: "壬戌，景眾濟江，遣輕騎至城下，問：「城內為誰？", literal: "On renxu, Jing's host crossed the river and sent light horse to the wall, asking: \"Who is inside the city?", idiomatic: "On renxu, Jing's host crossed the river and sent light horse to the wall: \"Who holds this city?" },
  { zh: "」答曰：「王領軍。", literal: "\" The answer came: \"Commander Wang.", idiomatic: "\" Came the answer: \"Commander Wang." },
  { zh: "」騎曰：「何不早降？", literal: "\" The horseman said: \"Why not surrender early?", idiomatic: "\" The horseman said: \"Why not surrender now?" },
  { zh: "」僧辯曰：「大軍但向荊州，此城自當非礙。", literal: "\" Senbian said: \"The great army is only bound for Jing province; this city will naturally be no obstacle.", idiomatic: "\" Senbian said: \"The main army is bound for Jing province; this city will not stand in your way." },
  { zh: "」騎去，頃之，執王珣等至城下，使說其弟琳。", literal: "\" The horseman left; presently they brought Wang Xun and others under the wall and had them persuade his younger brother Lin.", idiomatic: "\" The horseman left. Presently they brought Wang Xun and others to the wall to persuade his brother Lin." },
  { zh: "琳曰：「兄受命討賊，不能死難，曾不內慚，翻欲賜誘！", literal: "Lin said: \"Elder brother, charged to punish the rebel, could not die in the crisis—he never blushed inwardly, yet now would offer me inducement!", idiomatic: "Lin said: \"My brother was charged to punish the rebel, yet could not die in the crisis—he never blushed, and now would tempt me!" },
  { zh: "」取弓射之，珣慚而退。", literal: "\" He took his bow and shot; Xun withdrew in shame.", idiomatic: "\" He drew his bow and shot; Xun withdrew in shame." },
  { zh: "景肉薄百道攻城，城中鼓噪，矢石雨下。", literal: "Jing pressed close on a hundred routes to assault the city; inside, drums and shouts rose, arrows and stones rained down.", idiomatic: "Jing pressed the walls on a hundred fronts; inside, drums roared and arrows and stones rained down." },
  { zh: "景士卒死者甚眾，乃退。", literal: "Jing's soldiers died in great numbers; he then withdrew.", idiomatic: "Jing's men died in great numbers; he withdrew." },
  { zh: "僧辯遣輕兵出戰，凡十餘返，皆捷。", literal: "Senbian sent light troops out to fight; in more than ten rounds all were victories.", idiomatic: "Senbian sent light troops out; in more than ten sallies he won every time." },
  { zh: "景被甲在城下督戰，僧辯著綬、乘輿、奏鼓吹巡城，景望之，服其膽勇。", literal: "Jing wore armor below the wall directing battle; Senbian wore his sash, rode in a carriage, and had drums and pipes played as he circled the wall; Jing looked on and admired his courage.", idiomatic: "Jing wore armor below the wall directing the fight; Senbian wore his sash, rode in a carriage, and had drums and pipes played as he circled the wall. Jing looked on and marveled at his nerve." },
  { zh: "岳陽王察聞侯景克郢州，遣蔡大寶將兵一萬進據武寧，遣使至江陵，詐稱赴援。", literal: "Prince of Yueyang Cha, hearing Hou Jing had taken Ying province, sent Cai Dabao with ten thousand men to advance and seize Wuning, and sent an envoy to Jiangling falsely claiming he was coming to aid.", idiomatic: "Prince Cha of Yueyang, hearing Hou Jing had taken Ying province, sent Cai Dabao with ten thousand men to seize Wuning and sent an envoy to Jiangling falsely claiming he was coming to aid." },
  { zh: "眾議欲答以侯景已破，令其退軍。", literal: "The assembly debated answering that Hou Jing was already broken and ordering him to withdraw.", idiomatic: "The court debated answering that Hou Jing was already broken and ordering him to withdraw." },
  { zh: "湘東王繹曰：「今語以退軍，是趣之令進也。", literal: "Prince of Xiangdong Yi said: \"If we now speak of withdrawal, we are urging him to advance.", idiomatic: "Prince Xiao Yi of Xiangdong said: \"If we tell him to withdraw now, we are urging him to advance." },
  { zh: "」乃使謂大寶曰：「岳陽累啟連和，不相侵犯，卿那忽據武寧？", literal: "\" He then had someone tell Dabao: \"Yueyang has repeatedly declared alliance and mutual non-aggression—why do you suddenly hold Wuning?", idiomatic: "\" He sent word to Dabao: \"Yueyang has repeatedly pledged alliance and mutual non-aggression—why do you suddenly seize Wuning?" },
  { zh: "今當遣天門太守胡僧祐精甲二萬、鐵馬五千頓湕水，待時進軍。", literal: "We are now sending Tianmen Administrator Hu Sengyou with twenty thousand picked armor and five thousand iron horses to camp on the Jian, awaiting the hour to advance.", idiomatic: "We are sending Tianmen administrator Hu Sengyou with twenty thousand picked troops and five thousand iron horses to camp on the Jian, awaiting the hour to advance." },
  { zh: "」察聞之，召其軍還。", literal: "\" Cha heard this and recalled his army.", idiomatic: "\" Cha heard this and recalled his army." },
  { zh: "僧祐，南陽人也。", literal: "Sengyou was a man of Nanyang.", idiomatic: "Sengyou was from Nanyang." },
  { zh: "五月，魏隴西襄公李虎卒。", literal: "In the fifth month, Wei Duke of Longxi Xiang, Li Hu, died.", idiomatic: "In the fifth month, Li Hu, duke of Longxi Xiang in Wei, died." },
  { zh: "侯景晝夜攻巴陵，不克，軍中食盡，疾疫死傷太半。", literal: "Hou Jing attacked Baling day and night and could not take it; in the army food ran out, and pestilence killed and wounded more than half.", idiomatic: "Hou Jing assaulted Baling day and night and could not take it. Food ran out in the camp, and pestilence killed or wounded more than half his men." },
  { zh: "湘東王繹遣晉州刺史蕭惠正將兵援巴陵，惠正辭不堪，舉胡僧祐自代。", literal: "Prince of Xiangdong Yi sent Jinzhou Inspector Xiao Huizheng with troops to relieve Baling; Huizheng declined as unable and recommended Hu Sengyou in his place.", idiomatic: "Prince Xiao Yi of Xiangdong sent Jinzhou inspector Xiao Huizheng to relieve Baling. Huizheng declined and recommended Hu Sengyou instead." },
  { zh: "僧祐時坐謀議忤旨繫獄，繹即出之，拜武猛將軍，令赴援，戒之曰：「賊若水戰，但以大艦臨之，必克。", literal: "Sengyou was then imprisoned for counsel that offended the ruler's intent; Yi at once released him, made him Fierce Martial General, and ordered him to the relief, admonishing him: \"If the rebels fight on water, only press them with great ships and you will overcome.", idiomatic: "Sengyou was then in prison for counsel that had offended Yi. Yi released him at once, made him fierce martial general, and sent him to relieve Baling, warning him: \"If the rebels fight on water, press them with great ships and you will break them." },
  { zh: "若欲步戰，自可鼓棹直就巴丘，不須交鋒也。", literal: "If they wish land battle, you may simply beat the oars straight to Baqiu—no need to cross blades.", idiomatic: "If they want land battle, beat straight for Baqiu—no need to cross blades." },
  { zh: "」僧祐至湘浦，景遣任約帥銳卒五千據白□脊以待之。", literal: "\" Sengyou reached Xiangpu; Jing sent Ren Yue leading five thousand sharp troops to hold Bai□ Ridge and await him.", idiomatic: "\" Sengyou reached Xiangpu. Jing sent Ren Yue with five thousand sharp troops to hold Bai□ Ridge and wait." },
  { zh: "僧祐由它路西上，約謂其畏己，急追之，及於芊口，呼僧祐曰：「吳兒，何不早降！", literal: "Sengyou took another road west; Yue thought he feared him and pursued hotly; at Qian Mouth he called to Sengyou: \"Wu boy, why not surrender early!", idiomatic: "Sengyou took another road west. Yue thought he feared him and pursued hard. At Qian Mouth he shouted: \"Wu boy, why not surrender now!" },
  { zh: "走何所之！", literal: "Where are you running!", idiomatic: "Where do you think you are running!" },
  { zh: "」僧祐不應，潛引兵至赤沙亭；", literal: "\" Sengyou did not answer, secretly led his troops to Chisha Pavilion;", idiomatic: "\" Sengyou did not answer and secretly led his troops to Chisha Pavilion;" },
  { zh: "會信州刺史陸法和至，與之合軍。", literal: "he met Xinzhou Inspector Lu Fahe arriving and joined armies with him.", idiomatic: "there he met Xinzhou inspector Lu Fahe and joined forces." },
  { zh: "法和有異術，先隱於江陵百里洲，衣食居處，一如苦行沙門，或豫言吉凶，多中，人莫能測。", literal: "Fahe had strange arts; he had earlier hidden on Bailizhou at Jiangling; food, clothing, and dwelling were all like an ascetic monk's; sometimes he foretold fortune and disaster and mostly hit the mark—men could not fathom him.", idiomatic: "Fahe had strange arts. He had hidden on Bailizhou at Jiangling, living like an ascetic monk; he sometimes foretold fortune and disaster and mostly hit the mark—no one could fathom him." },
  { zh: "侯景之圍台城也，或問之曰：「事將何如？", literal: "When Hou Jing besieged the capital terrace city, someone asked him: \"How will matters go?", idiomatic: "When Hou Jing besieged the terrace city, someone asked him: \"How will this end?" },
  { zh: "」法和曰：「凡人取果，宜待熟時，不撩自落。", literal: "\" Fahe said: \"When ordinary men take fruit, they should wait until it is ripe; if you do not pluck it, it falls of itself.", idiomatic: "\" Fahe said: \"When men take fruit they should wait until it is ripe; leave it alone and it falls of itself." },
  { zh: "」固問之，法和曰：「亦克亦不克。", literal: "\" Pressed further, Fahe said: \"He may overcome and he may not overcome.", idiomatic: "\" Pressed further, Fahe said: \"He may win and he may not win." },
  { zh: "」及任約向江陵，法和自請擊之，繹許之。", literal: "\" When Ren Yue marched on Jiangling, Fahe volunteered to strike him and Yi approved.", idiomatic: "\" When Ren Yue marched on Jiangling, Fahe volunteered to strike him and Yi agreed." },
  { zh: "壬寅，約至赤亭。", literal: "On renyin, Yue reached Chiting.", idiomatic: "On renyin, Yue reached Chiting." },
  { zh: "六月，甲辰，僧祐、法和縱兵擊之，約兵大潰，殺溺死者甚眾，擒約送江陵。", literal: "In the sixth month, on jiachen, Sengyou and Fahe loosed their troops and struck; Yue's army broke badly; killed and drowned were very many; they captured Yue and sent him to Jiangling.", idiomatic: "In the sixth month, on jiachen, Sengyou and Fahe attacked. Yue's army collapsed; vast numbers were killed or drowned; they captured Yue and sent him to Jiangling." },
  { zh: "景聞之，乙巳，焚營宵遁。", literal: "Jing heard this; on yisi he burned camp and fled by night.", idiomatic: "Jing heard this. On yisi he burned camp and fled by night." },
  { zh: "以丁和為郢州刺史，留宋子仙等，眾號二萬，戍郢城；", literal: "He made Ding He Yingzhou Inspector, left Song Zixian and others, their host numbering twenty thousand, to garrison Ying city;", idiomatic: "He made Ding He Yingzhou inspector, left Song Zixian and others—twenty thousand in all—to garrison Ying city;" },
  { zh: "別將支化仁鎮魯山，范希榮行江州事，儀同三司任延和、晉州刺史夏侯威生守晉州。", literal: "detached general Zhi Huaren garrisoned Lushan, Fan Xirong acted for Jiang province, Masters of Protocol Ren Yanhe and Jinzhou Inspector Xiahou Weisheng held Jin province.", idiomatic: "detached general Zhi Huaren held Lushan, Fan Xirong acted for Jiang province, and masters of protocol Ren Yanhe and Jinzhou inspector Xiahou Weisheng held Jin province." },
  { zh: "景與麾下兵數千，順流而下。", literal: "Jing with several thousand troops under his command went downstream.", idiomatic: "Jing went downstream with several thousand men." },
  { zh: "丁和以大石磕殺鮑泉及虞預，沈於黃鶴磯。", literal: "Ding He killed Bao Quan and Yu Yu with a great stone pestle and sank them at Yellow Crane Rock.", idiomatic: "Ding He killed Bao Quan and Yu Yu with a stone pestle and sank them at Yellow Crane Rock." },
  { zh: "任約至江陵，繹赦之。", literal: "Ren Yue reached Jiangling; Yi pardoned him.", idiomatic: "Ren Yue reached Jiangling; Yi pardoned him." },
  { zh: "徐文盛坐怨望，下獄死。", literal: "Xu Wensheng was charged with resentment and disaffection, imprisoned, and died.", idiomatic: "Xu Wensheng was charged with disaffection, imprisoned, and died." },
  { zh: "巴州刺史余孝頃遣兄子僧重將兵救鄱陽，于慶退走。", literal: "Bazhou Inspector Yu Xiaoqing sent his elder brother's son Sengzhong with troops to rescue Poyang; Yu Qing withdrew.", idiomatic: "Bazhou inspector Yu Xiaoqing sent his nephew Sengzhong to relieve Poyang; Yu Qing withdrew." },
  { zh: "繹以王僧辯為征東將軍、尚書令，胡僧祐等皆進位號，使引兵東下。", literal: "Yi made Wang Senbian Campaign-East General and Director of the Masters of Writing; Hu Sengyou and others all advanced in rank and title, and had them lead troops east.", idiomatic: "Yi made Wang Senbian campaign-east general and director of the masters of writing; Hu Sengyou and others were all promoted, and he had them lead troops east." },
  { zh: "陸法和請還，既至，謂繹曰：「侯景自然平矣，蜀賊將至，請守險以待之。", literal: "Lu Fahe asked to return; once arrived, he told Yi: \"Hou Jing will naturally be pacified; Shu rebels are about to come—please hold the passes and await them.", idiomatic: "Lu Fahe asked to return. Once back, he told Yi: \"Hou Jing will fall of himself. Shu rebels are coming—hold the passes and wait." },
  { zh: "」乃引兵屯峽口。", literal: "\" He then led troops to camp at Xiakou.", idiomatic: "\" He then camped at the gorge mouth." },
  { zh: "庚申，王僧辯至漢口，先攻魯山，擒支化仁送江陵。", literal: "On gengshen, Wang Senbian reached Hankou, first attacked Lushan, captured Zhi Huaren, and sent him to Jiangling.", idiomatic: "On gengshen, Wang Senbian reached Hankou, stormed Lushan first, captured Zhi Huaren, and sent him to Jiangling." },
  { zh: "辛酉，攻郢州，克其羅城，斬首千級。", literal: "On xinyou, he attacked Ying province, took its outer wall, and beheaded a thousand heads.", idiomatic: "On xinyou, he attacked Ying province, took the outer wall, and took a thousand heads." },
  { zh: "宋子仙退據金城，僧辯四面起土山攻之。", literal: "Song Zixian withdrew to hold the Golden Wall; Senbian raised earthworks on four sides to attack.", idiomatic: "Song Zixian withdrew to the Golden Wall; Senbian raised earthworks on every side." },
  { zh: "豫州刺史荀朗自巢湖出濡須邀景，破其後軍，景奔歸，船前後相失。", literal: "Yuzhou Inspector Xun Lang came from Chaohu through Ruxu to intercept Jing, broke his rear guard; Jing fled back, and ships before and behind lost one another.", idiomatic: "Yuzhou inspector Xun Lang came from Chaohu through Ruxu to intercept Jing and broke his rear. Jing fled back, and his fleet scattered." },
  { zh: "太子船入樅陽浦，船中腹心皆勸太子因此入北，太子曰：「自國家喪敗，志不圖生，主上蒙塵，寧忍違離左右！", literal: "The crown prince's ship entered Zongyang inlet; trusted men in the ship all urged the prince to use this chance to go north; the prince said: \"Since the state's ruin I have had no thought of living; the sovereign suffers dust—how could I bear to leave his side!", idiomatic: "The crown prince's ship entered Zongyang inlet. His trusted men all urged him to slip north. The prince said: \"Since the state's ruin I have had no thought of living. The sovereign suffers exile—how could I leave his side!" },
  { zh: "吾今若去，乃是叛父，非避賊也。", literal: "If I go now, it is betraying my father, not avoiding the rebel.", idiomatic: "If I go now, I betray my father—I am not fleeing the rebel." },
  { zh: "」因涕泗嗚咽，即命前進。", literal: "\" He wept with running tears and at once ordered advance.", idiomatic: "\" He wept aloud and ordered the ship forward." },
  { zh: "甲子，宋子仙等困蹙，乞輸郢城，身還就景；", literal: "On jiazi, Song Zixian and the others were hard pressed and begged to surrender Ying city and return in person to Jing;", idiomatic: "On jiazi, Song Zixian and the rest, hard pressed, offered to surrender Ying city and return to Jing in person;" },
  { zh: "王僧辯偽許之，命給船百艘以安其意。", literal: "Wang Senbian falsely agreed and ordered a hundred ships given to settle their minds.", idiomatic: "Wang Senbian feigned agreement and ordered a hundred ships provided to calm them." },
  { zh: "子仙謂為信然，浮舟將發，僧辯命杜龕帥精勇千人攀堞而上，鼓噪奄進，水軍主宋遙帥樓船，暗江雲合。", literal: "Zixian thought it true, floated their boats to set out; Senbian ordered Du Kan leading a thousand sharp brave men to climb the parapet, drums and shouts bursting forward; naval commander Song Yao led tower ships, and on the dark river clouds of them closed in.", idiomatic: "Zixian believed him. As their boats were about to sail, Senbian ordered Du Kan with a thousand picked men up the wall in a sudden rush of drums and shouts; naval commander Song Yao closed on them with tower ships on the dark river." },
  { zh: "子仙且戰且走，至白楊浦，大破之。", literal: "Zixian fought as he fled; at Baiyang Ford they were routed badly.", idiomatic: "Zixian fought as he fled. At Baiyang Ford Senbian broke them utterly." },
  { zh: "周鐵虎生擒子仙及丁和，送江陵，殺之。", literal: "Zhou Tiehu captured Zixian and Ding He alive and sent them to Jiangling, where they were killed.", idiomatic: "Zhou Tiehu took Zixian and Ding He alive and sent them to Jiangling, where they were executed." },
  { zh: "庚午，齊主以司馬子如高祖之舊，復以為太尉。", literal: "On gengwu, the Qi ruler, because Sima Ziru was an old companion of the High Ancestor, again made him Grand Commandant.", idiomatic: "On gengwu, the Qi emperor, because Sima Ziru had been an old companion of the founding emperor, restored him as grand commandant." },
  { zh: "江安侯圓正為西陽太守，寬和好施，歸附者眾，有兵一萬。", literal: "Marquis of Jiang'an Yuanzheng was Xiyang Administrator, generous and mild and fond of giving; those who submitted were many; he had ten thousand troops.", idiomatic: "Marquis Yuanzheng of Jiang'an was Xiyang administrator—generous, mild, and open-handed. Many submitted to him; he had ten thousand troops." },
  { zh: "湘東王繹欲圖之，署為平南將軍。", literal: "Prince of Xiangdong Yi wished to scheme against him and appointed him Pacification-South General.", idiomatic: "Prince Xiao Yi of Xiangdong meant to destroy him and appointed him pacification-south general." },
  { zh: "及至，弗見，使南平王恪與之飲，醉，因囚之內省，分其部曲，使人告其罪。", literal: "When he arrived, Yi would not see him; he had Prince of Nanping Ke drink with him; when drunk, he imprisoned him in the inner bureau, divided his followers, and had someone announce his crimes.", idiomatic: "When he arrived, Yi refused to see him. He had Prince Ke of Nanping drink with him; when Yuanzheng was drunk, Yi imprisoned him in the inner bureau, divided his followers, and published his crimes." },
  { zh: "荊、益之釁自此起矣。", literal: "The feud between Jing and Yi began from this.", idiomatic: "The breach between Jing and Yi began here." },
  { zh: "陳霸先引兵發南康，灨石舊有二十四灘，會水暴漲數丈，三百里間，巨石皆沒，霸先進頓西昌。", literal: "Chen Baxian led troops out from Nankang; Ganshi had twenty-four old rapids; it happened that the waters rose several zhang in a sudden flood; for three hundred li great stones were all submerged; Baxian advanced and halted at Xichang.", idiomatic: "Chen Baxian marched from Nankang. Ganshi had twenty-four old rapids; the river rose several zhang in a sudden flood and submerged the great stones for three hundred li. Baxian halted at Xichang." },
  { zh: "鐵勒將伐柔然，突厥酋長土門邀擊，破之，盡降其眾五萬餘落。", literal: "Tiele were about to attack Rouran; Tujue chief Tumen intercepted and struck, broke them, and all their following of more than fifty thousand clans submitted.", idiomatic: "The Tiele were marching on Rouran when Tujue chief Tumen intercepted them, routed them, and took the submission of more than fifty thousand clans." },
  { zh: "土門恃其強盛，求婚於柔然，柔然頭兵可汗大怒，使人詈辱之曰：「爾，我之鍛奴也，何敢發是言！", literal: "Tumen relied on his strength, sought marriage with Rouran; Rouran's Toubing Khan was greatly angered and sent a man to revile and insult him, saying: \"You are my forge-slave—how dare you speak such words!", idiomatic: "Tumen, relying on his strength, sought marriage with Rouran. Rouran's Toubing Khan was furious and sent a man to revile him: \"You are my forge-slave—how dare you speak such words!" },
  { zh: "」土門亦怒，殺其使者，遂與之絕，而求婚於魏；", literal: "\" Tumen too was angry, killed his envoy, broke with them, and sought marriage with Wei;", idiomatic: "\" Tumen too was angry, killed the envoy, broke with Rouran, and sought marriage with Wei;" },
  { zh: "魏丞相泰以長樂公主妻之。", literal: "Wei Chancellor Tai gave him Princess Changle as wife.", idiomatic: "Chancellor Yuwen Tai gave him Princess Changle as wife." },
  { zh: "秋，七月，乙亥，湘東王繹以長沙王韶監郢州事。", literal: "In autumn, the seventh month, on yihai, Prince of Xiangdong Yi made Prince of Changsha Shao oversee Ying province affairs.", idiomatic: "In autumn, the seventh month, on yihai, Prince Xiao Yi of Xiangdong made Prince Shao of Changsha oversee Ying province." },
  { zh: "丁亥，侯景還至建康。", literal: "On dinghai, Hou Jing returned to Jiankang.", idiomatic: "On dinghai, Hou Jing returned to Jiankang." },
  { zh: "于慶自鄱陽還豫章，侯瑱門拒之，慶走江州，據郭默城。", literal: "Yu Qing returned from Poyang to Yuzhang; Hou Zhen shut his gates against him; Qing fled to Jiang province and held Guo Mo's city.", idiomatic: "Yu Qing returned from Poyang to Yuzhang. Hou Zhen shut him out. Qing fled to Jiang province and held Guo Mo's city." },
  { zh: "繹以瑱兗州刺史。", literal: "Yi made Zhen Yanzhou Inspector.", idiomatic: "Yi made Zhen Yanzhou inspector." },
  { zh: "景悉殺瑱弟。", literal: "Jing killed all of Zhen's younger brothers.", idiomatic: "Jing killed all of Zhen's younger brothers." },
  { zh: "辛丑，王僧辯乘勝下湓城，陳霸先帥所部三萬人將會之，屯於巴丘。", literal: "On xinchou, Wang Senbian, riding victory, went downstream to Pencheng; Chen Baxian led his division of thirty thousand men intending to join him and encamped at Baqiu.", idiomatic: "On xinchou, Wang Senbian pressed his victory to Pencheng. Chen Baxian led thirty thousand men to join him and camped at Baqiu." },
  { zh: "西軍乏食，霸先有糧五十萬石，分三十萬石以資之。", literal: "The western army lacked food; Baxian had five hundred thousand shi of grain and gave three hundred thousand shi to supply them.", idiomatic: "The western army was starving. Baxian had five hundred thousand shi of grain and gave them three hundred thousand." },
  { zh: "八月，壬寅朔，王僧辯前軍襲于慶，慶棄郭默城走，范希榮亦棄尋陽城走。", literal: "In the eighth month, on the first day renyin of the month, Wang Senbian's vanguard raided Yu Qing; Qing abandoned Guo Mo's city and fled; Fan Xirong also abandoned Xunyang city and fled.", idiomatic: "In the eighth month, on renyin, the new moon, Wang Senbian's vanguard struck Yu Qing. Qing abandoned Guo Mo's city and fled; Fan Xirong abandoned Xunyang as well." },
  { zh: "晉熙王僧振等起兵圍郡城，僧辯遣沙州刺史丁道貴助之，任延和等棄城走。", literal: "Prince of Jinxi Sengzhen and others raised troops and besieged the commandery city; Senbian sent Shazhou Inspector Ding Daogui to aid them; Ren Yanhe and the others abandoned the city and fled.", idiomatic: "Prince Sengzhen of Jinxi and others besieged the commandery city. Senbian sent Shazhou inspector Ding Daogui to help; Ren Yanhe and the rest abandoned the city and fled." },
  { zh: "湘東王繹命僧辯且頓尋陽以待諸軍之集。", literal: "Prince of Xiangdong Yi ordered Senbian to halt at Xunyang and await the gathering of the armies.", idiomatic: "Prince Xiao Yi of Xiangdong ordered Senbian to halt at Xunyang until the armies gathered." },
  { zh: "初，景既克建康，常言吳兒怯弱，易以掩取。", literal: "Earlier, after Jing had taken Jiankang, he often said the Wu men were timid and weak and easy to seize in a surprise.", idiomatic: "Earlier, after Jing took Jiankang, he often said the Wu men were timid and easy to overrun." },
  { zh: "當須拓定中原，然後為帝。", literal: "He must first extend and settle the central plains, and only then become emperor.", idiomatic: "He must first win the central plains, and only then take the throne." },
  { zh: "景尚帝女溧陽公主，嬖之，妨於政事。", literal: "Jing favored the emperor's daughter, Princess of Liyang, doted on her, and she hindered state affairs.", idiomatic: "Jing favored the emperor's daughter, the Princess of Liyang, doted on her, and she interfered in government." },
  { zh: "王偉屢諫，景以告主，主有惡言。", literal: "Wang Wei remonstrated repeatedly; Jing told the princess; she had harsh words.", idiomatic: "Wang Wei remonstrated again and again. Jing told the princess; she answered with harsh words." },
  { zh: "偉恐為所讒，因說景除帝。", literal: "Wei feared being slandered by her and therefore urged Jing to remove the emperor.", idiomatic: "Wei feared her slanders and urged Jing to remove the emperor." },
  { zh: "及景自巴陵敗歸，猛將多死，自恐不能久存，欲早登大位。", literal: "When Jing returned defeated from Baling, many fierce generals were dead; he himself feared he could not long endure and wished to mount the throne early.", idiomatic: "When Jing returned defeated from Baling, many of his best generals were dead. He feared he could not last and wished to take the throne at once." },
  { zh: "王偉曰：「自古移鼎，必須廢立，既示我威權，且絕彼民望。", literal: "Wang Wei said: \"Since antiquity, shifting the cauldron has required deposition and installation—both to show our aweful authority and to cut off their people's hope.", idiomatic: "Wang Wei said: \"Since antiquity, shifting the cauldron has required deposition and enthronement—both to show our power and to cut off the people's hope." },
  { zh: "」景從之。", literal: "\" Jing followed this.", idiomatic: "\" Jing agreed." },
  { zh: "使前壽光殿學士謝昊為詔書，以為「弟侄爭立，星辰失次，皆由朕非正緒，召亂致災，宜禪位於豫章王棟。", literal: "He had former Shouguang Hall academician Xie Hao draft an edict, stating that \"younger brothers and nephews contended for the throne, the stars lost their order—all because I am not of the true line, summoning chaos and bringing disaster; the throne should be yielded to Prince of Yuzhang Dong.", idiomatic: "He had former Shouguang Hall academician Xie Hao draft an edict claiming that \"nephews contended for the throne and the stars lost their order—all because I am not of the true line, summoning chaos and disaster. The throne should pass to Prince Dong of Yuzhang." },
  { zh: "」使呂季略繼入，逼帝書之。", literal: "\" He sent Lü Jilüe in next to force the emperor to write it.", idiomatic: "\" He sent Lü Jilüe in next to force the emperor to sign." },
  { zh: "棟，歡之子也。", literal: "Dong was Huan's son.", idiomatic: "Dong was the son of Huan." },
  { zh: "戊午，景遣衛尉卿彭雋等帥兵入殿，廢帝為晉安王，幽於永福省，悉撤內外侍衛，使突騎左右守之，牆垣悉布枳棘。", literal: "On wuwu, Jing sent Commandant of the Guard Peng Juan and others leading troops into the hall, deposed the emperor as Prince of Jin'an, confined him in Yongfu Palace, removed all inner and outer guards, set nomad-cavalry guards to watch him, and planted thorn hedges on every wall.", idiomatic: "On wuwu, Jing sent commandant of the guard Peng Juan and others into the hall, deposed the emperor as Prince of Jin'an, and confined him in Yongfu Palace. He stripped all guards, set nomad-cavalry guards to watch him, and planted thorn hedges on every wall." },
  { zh: "庚申，下詔迎豫章王棟。", literal: "On gengshen, an edict was issued welcoming Prince of Yuzhang Dong.", idiomatic: "On gengshen, an edict welcomed Prince Dong of Yuzhang." },
  { zh: "棟時幽拘，廩餼甚薄，仰蔬茹為食。", literal: "Dong was then under close confinement; his grain allowance was very thin; he lived on vegetables alone.", idiomatic: "Dong was then confined; his ration was meager; he lived on vegetables alone." },
  { zh: "方與妃張氏鉏葵，法駕奄至，棟驚，不知所為，泣而升輦。", literal: "He was just hoeing melons with his consort Lady Zhang when the imperial equipage suddenly arrived; Dong was startled, knew not what to do, wept, and mounted the carriage.", idiomatic: "He was hoeing melons with his consort Lady Zhang when the imperial train suddenly arrived. Dong was startled, wept, and mounted the carriage." },
  { zh: "景殺哀太子大器、尋陽王大心、西陽王大鈞、建平王大球、義安王大昕及王侯在建康者二十餘人。", literal: "Jing killed Lamented crown prince Daqi, Prince of Xunyang Daxin, Prince of Xiyang Dajun, Prince of Jianping Daqiu, Prince of Yi'an Daxin, and more than twenty princes and marquises in Jiankang.", idiomatic: "Jing killed crown prince Daqi, Prince Daxin of Xunyang, Prince Dajun of Xiyang, Prince Daqiu of Jianping, Prince Daxin of Yi'an, and more than twenty princes and marquises in Jiankang." },
  { zh: "太子神明端嶷，於景黨未嘗屈意，所親竊問之，太子曰：「賊若於事義，未須見殺，吾雖陵慢呵叱，終不敢言。", literal: "The crown prince was bright in spirit and upright in bearing; toward Jing's faction he never bent his will; a close attendant secretly asked him; the prince said: \"If the rebel still cares for righteousness, he need not kill me yet; though I insult and scold him, in the end he will not dare speak.", idiomatic: "The crown prince was bright of spirit and upright in bearing; toward Jing's men he never bent. A close attendant asked him privately. The prince said: \"If the rebel still cares for righteousness, he need not kill me yet. Though I insult and scold him, in the end he will not dare answer." },
  { zh: "若見殺時至，雖一日百拜，亦無所益。", literal: "If the hour to kill me has come, though I bow a hundred times in a day, it will do no good.", idiomatic: "If the hour to kill me has come, a hundred bows in a day will do no good." },
  { zh: "」又曰：「殿下今居困□厄，而神貌怡然，不貶平日，何也？", literal: "\" Another said: \"Your Highness now dwells in dire □ distress, yet your spirit and face are at ease, not diminished from ordinary days—why?", idiomatic: "\" Another asked: \"Your Highness now dwells in dire □ distress, yet your spirit and face are at ease, undiminished from ordinary days—why?" },
  { zh: "」太子曰：「吾自度死日必在賊前，若諸叔能滅賊，賊必先見殺，然後就死。", literal: "\" The prince said: \"I myself reckon my death-day must come before the rebel's; if my uncles can destroy the rebel, the rebel will be killed first, and only then will I go to death.", idiomatic: "\" The prince said: \"I reckon I must die before the rebel. If my uncles destroy him, he will be killed first, and only then will I die." },
  { zh: "若其不然，賊亦殺我以取富貴，安能以必死之命為無益之愁乎！", literal: "If not, the rebel will also kill me to win wealth and honor—how could I take a life certain to die and spend it in useless grief!", idiomatic: "If not, the rebel will kill me anyway for wealth and rank—why spend a life already doomed on useless grief!" },
  { zh: "」及難，太子顏色不變，徐曰：「久知此事，嗟其晚耳！", literal: "\" When disaster came, the prince's color did not change; he said calmly: \"I have long known this—only regret it is late!", idiomatic: "\" When the end came, the prince's color did not change. He said calmly: \"I have long known this—only regret it came late!" },
  { zh: "」刑者將以衣帶絞之，太子曰：「此不能見殺。", literal: "\" The executioners were about to strangle him with his sash; the prince said: \"That cannot kill me.", idiomatic: "\" The executioners were about to strangle him with his sash. The prince said: \"That will not kill me." },
  { zh: "」命取帳繩絞之而絕。", literal: "\" He ordered them to take tent rope to strangle him until he was dead.", idiomatic: "\" He ordered tent rope—and died." },
  { zh: "壬戌，棟即帝位。", literal: "On renxu, Dong took the throne.", idiomatic: "On renxu, Dong took the throne." },
  { zh: "大赦，改元天正。", literal: "A general amnesty was proclaimed; the era name was changed to Tianzheng.", idiomatic: "A general amnesty was proclaimed; the era name was changed to Tianzheng." },
  { zh: "太尉郭元建聞之，自秦郡馳還，謂景曰：「主上先帝太子，既無愆失，何得廢之！", literal: "Grand Commandant Guo Yuanjian heard this, galloped back from Qin Commandery, and said to Jing: \"The sovereign was the former emperor's crown prince and had no fault—how could you depose him!", idiomatic: "Grand commandant Guo Yuanjian heard this, galloped back from Qin commandery, and said to Jing: \"The sovereign was the late emperor's crown prince and had no fault—how could you depose him!" },
  { zh: "」景曰：「王偉勸吾，云『早除民望』。", literal: "\" Jing said: \"Wang Wei urged me, saying 'Remove the people's hope early.'", idiomatic: "\" Jing said: \"Wang Wei urged me, saying 'Remove the people's hope early.'\"" },
  { zh: "吾故從之以安天下。", literal: "I therefore followed this to settle the realm.", idiomatic: "I followed him to settle the realm." },
  { zh: "」元建曰：「吾挾天子令諸侯，猶懼不濟；", literal: "\" Yuanjian said: \"Holding the Son of Heaven to command the feudal lords, I still fear failure;", idiomatic: "\" Yuanjian said: \"Holding the Son of Heaven to command the lords, I still fear failure;" },
  { zh: "無故廢之，乃所以自危，何安之有！", literal: "to depose him without cause is how one brings danger on oneself—what settlement is there!", idiomatic: "to depose him without cause is to court ruin—what settlement is there!" },
  { zh: "」景欲迎帝復位，以棟為太孫。", literal: "\" Jing wished to welcome the emperor back and make Dong grand heir.", idiomatic: "\" Jing wished to restore the emperor and make Dong grand heir." },
  { zh: "王偉曰：「廢立大事，豈可數改邪！", literal: "Wang Wei said: \"Deposition and installation are a great matter—how can they be changed again and again!", idiomatic: "Wang Wei said: \"Deposition and enthronement are a great matter—how can they be changed again and again!" },
  { zh: "」乃止。", literal: "\" He then stopped.", idiomatic: "\" He stopped." },
  { zh: "乙丑，景又使使殺南海王大臨於吳郡，南郡王大連於姑孰，安陸王大春於會稽，高唐王大壯於京口。", literal: "On yichou, Jing again sent envoys to kill Prince of Nanhai Dalin at Wu Commandery, Prince of Nanjun Dalian at Gudu, Prince of Anlu Dachun at Kuaiji, and Prince of Gaotang Dazhuang at Jingkou.", idiomatic: "On yichou, Jing sent envoys to kill Prince Dalin of Nanhai at Wu commandery, Prince Dalian of Nanjun at Gudu, Prince Dachun of Anlu at Kuaiji, and Prince Dazhuang of Gaotang at Jingkou." },
  { zh: "以太子妃賜郭元建，元建曰：「豈有皇太子妃乃為人妾乎！", literal: "He gave the crown prince's consort to Guo Yuanjian; Yuanjian said: \"How could a crown prince's consort become another man's concubine!", idiomatic: "He gave the crown prince's consort to Guo Yuanjian. Yuanjian said: \"How could a crown prince's consort become another man's concubine!" },
  { zh: "」竟不與相見，聽使入道。", literal: "\" In the end he would not meet her and allowed her to enter the Way.", idiomatic: "\" In the end he would not see her and allowed her to take vows." },
  { zh: "丙寅，追尊昭明太子為昭明皇帝，豫章安王為安皇帝，金華敬妃為敬太皇太后，豫章太妃王氏為皇太后，妃張氏為皇后。", literal: "On bingyin, he posthumously honored the Luminous Heir as Emperor Zhaoming, the Peaceful Prince of Yuzhang as Emperor An, the Revered Consort of Jinhua as Grand Empress Dowager Jing, the Grand Consort of Yuzhang Lady Wang as Empress Dowager, and Consort Zhang as Empress.", idiomatic: "On bingyin, he posthumously honored the Luminous Heir as Emperor Zhaoming, the Peaceful Prince of Yuzhang as Emperor An, the Revered Consort of Jinhua as Grand Empress Dowager Jing, Lady Wang as empress dowager, and Lady Zhang as empress." },
  { zh: "以劉神茂為司空。", literal: "He made Liu Shenmao Minister of Works.", idiomatic: "He made Liu Shenmao minister of works." },
  { zh: "九月，癸巳，齊主如趙、定二州，遂如晉陽。", literal: "In the ninth month, on guisi, the Qi ruler went to Zhao and Ding provinces and then to Jinyang.", idiomatic: "In the ninth month, on guisi, the Qi emperor went to Zhao and Ding provinces and then to Jinyang." },
  { zh: "己亥，湘東王繹以尚書令王僧辯為江州刺史，江州刺史陳霸先為東揚州刺史。", literal: "On jihai, Prince of Xiangdong Yi made Director of the Masters of Writing Wang Senbian Jiangzhou Inspector and Jiangzhou Inspector Chen Baxian Eastern Yangzhou Inspector.", idiomatic: "On jihai, Prince Xiao Yi of Xiangdong made director of the masters of writing Wang Senbian Jiangzhou inspector and Jiangzhou inspector Chen Baxian Eastern Yangzhou inspector." },
  { zh: "王偉說侯景弒太宗以絕眾心，景從之。", literal: "Wang Wei urged Hou Jing to assassinate the Grand Ancestor to cut off the people's hearts; Jing followed this.", idiomatic: "Wang Wei urged Hou Jing to assassinate Emperor Jianwen to cut off the people's loyalty; Jing agreed." },
  { zh: "冬，十月，壬寅夜，偉與左衛將軍彭雋、王修纂進酒於太宗曰：「丞相以陛下幽憂既久，使臣等來上壽。", literal: "In winter, the tenth month, on the night of renyin, Wei with Left Guard General Peng Juan and Wang Xiuzuan brought wine to the Grand Ancestor, saying: \"The chancellor, because Your Majesty has long been in hidden grief, sent us to offer longevity.", idiomatic: "In winter, the tenth month, on the night of renyin, Wei with left guard general Peng Juan and Wang Xiuzuan brought wine to Emperor Jianwen, saying: \"The chancellor, seeing Your Majesty long in grief, sent us to offer longevity." },
  { zh: "」太宗笑曰：「已禪帝位，何得言陛下！", literal: "\" The Grand Ancestor smiled and said: \"The throne has already been yielded—how can you speak of 'Your Majesty'!", idiomatic: "\" Emperor Jianwen smiled and said: \"The throne has already been yielded—how can you say 'Your Majesty'!" },
  { zh: "此壽酒，將不盡此乎！", literal: "This longevity wine—will it not be finished here!", idiomatic: "This longevity wine—you mean to finish me here!" },
  { zh: "」於是雋等繼曲項琵琶，與太宗極飲。", literal: "\" Then Juan and the others in succession played the bent-neck pipa and drank to the utmost with the Grand Ancestor.", idiomatic: "\" Then Juan and the others played the bent-neck pipa in turn and drank with Emperor Jianwen to the end." },
  { zh: "太宗知將見殺，因盡醉，曰：「不圖為樂之至於斯也！", literal: "The Grand Ancestor knew he was about to be killed and therefore got fully drunk, saying: \"I never imagined pleasure could reach this point!", idiomatic: "Emperor Jianwen knew he was about to die and drank himself blind, saying: \"I never imagined pleasure could reach this point!" },
  { zh: "」既醉而寢。", literal: "\" When drunk he slept.", idiomatic: "\" When he was drunk he slept." },
  { zh: "偉乃出，雋進土囊，修纂坐其上而殂。", literal: "Wei then went out; Juan brought in an earth sack; Xiuzuan sat on it and the emperor died.", idiomatic: "Wei went out. Juan brought in an earth sack; Xiuzuan sat on it and the emperor died." },
  { zh: "偉撤戶扉為棺，遷殯於城北酒庫中。", literal: "Wei took door panels for a coffin and moved the bier to the wine storehouse north of the city.", idiomatic: "Wei used door panels for a coffin and moved the body to the wine storehouse north of the city." },
  { zh: "太宗自幽縶之後，無復侍者及紙，乃書壁及板障，為詩及文數百篇，辭甚淒愴。", literal: "After the Grand Ancestor's close confinement he had no attendants or paper again; he wrote on walls and partition boards poems and prose of several hundred pieces, their words very mournful.", idiomatic: "After his confinement Emperor Jianwen had no attendants or paper; he wrote on walls and partition boards several hundred poems and essays, their words very mournful." },
  { zh: "景謚曰明皇帝，廟號高宗。", literal: "Jing gave the posthumous title Emperor Ming and temple name High Ancestor.", idiomatic: "Jing gave the posthumous title Emperor Ming and temple name High Ancestor." },
  { zh: "侯景之逼江陵也，湘東王繹求援於魏，命梁、秦二州刺史宜豐侯循以南鄭與魏，召循還江陵。", literal: "When Hou Jing pressed Jiangling, Prince of Xiangdong Yi sought aid from Wei, ordered Liang and Qin province inspectors Marquis of Yifeng Xun to give Nanzheng to Wei, and summoned Xun back to Jiangling.", idiomatic: "When Hou Jing pressed Jiangling, Prince Xiao Yi of Xiangdong sought aid from Wei, ordered Liang and Qin inspector Marquis Xun of Yifeng to yield Nanzheng to Wei, and summoned Xun back to Jiangling." },
  { zh: "循以無故輸城，非忠臣之節，報曰：「請待改命。", literal: "Xun, holding that to surrender a city without cause was not a loyal servant's conduct, replied: \"Please await a revised order.", idiomatic: "Xun held that to surrender a city without cause was not a loyal man's conduct and replied: \"Please await a revised order." },
  { zh: "」魏太師泰遣大將軍達奚武將兵三萬取漢中，又遣大將軍王雄出子午谷，攻上津。", literal: "\" Wei Grand Preceptor Tai sent Grand General Daxi Wu with thirty thousand men to take Hanzhong, and also sent Grand General Wang Xiong out through Ziwu Valley to attack Shangjin.", idiomatic: "\" Grand preceptor Yuwen Tai sent grand general Daxi Wu with thirty thousand men to take Hanzhong and grand general Wang Xiong through Ziwu Valley against Shangjin." },
  { zh: "循遣記室參軍沛人劉璠求援於武陵王紀，紀遣潼州刺史楊乾運救之。", literal: "Xun sent recorder Liu Fan of Pei to seek aid from Prince of Wuling Ji; Ji sent Tongzhou Inspector Yang Qianyun to rescue him.", idiomatic: "Xun sent recorder Liu Fan of Pei to Prince Ji of Wuling for aid; Ji sent Tongzhou inspector Yang Qianyun to relieve him." },
  { zh: "循，恢之子也。", literal: "Xun was Hui's son.", idiomatic: "Xun was Hui's son." },
  { zh: "王僧辯等聞太宗殂，丙辰，啟湘東王繹，請上尊號；", literal: "Wang Sengbian and others, hearing that Emperor Taizong had died, on bingchen memorialized Prince Yi of Xiangdong and asked that he take the supreme title.", idiomatic: "Wang Sengbian and others, learning that Emperor Taizong was dead, on bingchen memorialized Prince Xiao Yi of Xiangdong and urged him to take the supreme title." },
  { zh: "繹弗許。", literal: "Yi would not consent.", idiomatic: "Yi would not consent." },
  { zh: "司空、東道行台劉神茂聞侯景自巴丘敗還，陰謀叛景，吳中士大夫咸勸之；", literal: "Minister of Works and Eastern Route Mobile Headquarters Liu Shenma, hearing that Hou Jing had been defeated at Baling and was returning, secretly plotted to rebel against Jing; the gentry of Wu all urged him on.", idiomatic: "Minister of Works and eastern-route mobile headquarters Liu Shenma, hearing that Hou Jing had been beaten at Baling and was retreating, secretly plotted rebellion; the gentry of Wu all urged him on." },
  { zh: "乃與儀同三司尹思合、劉歸義、王曄、雲麾將軍元頵等據東陽以應江陵，遣頵及別將李佔下據建德江口。", literal: "He then joined with Palace Attendant of the Third Rank Yin Sihe, Liu Guiyi, Wang Ye, and Cloud-Banner General Yuan Yun and others to hold Dongyang in response to Jiangling, and sent Yun and detached commander Li Zhan downstream to seize the Jiande river mouth.", idiomatic: "He then joined Palace Attendant of the Third Rank Yin Sihe, Liu Guiyi, Wang Ye, and Cloud-Banner General Yuan Yun and others in holding Dongyang to answer Jiangling, and sent Yun and detached commander Li Zhan downstream to seize the Jiande river mouth." },
  { zh: "張彪攻永嘉，克之。", literal: "Zhang Biao attacked Yongjia and took it.", idiomatic: "Zhang Biao attacked Yongjia and took it." },
  { zh: "新安民程靈洗起兵據郡以應神茂。", literal: "The people of Xin'an, Cheng Lingxi, raised troops and held the commandery in support of Shenma.", idiomatic: "Cheng Lingxi of Xin'an raised troops, held the commandery, and answered Shenma." },
  { zh: "於是浙江以東皆附江陵。", literal: "Thereupon all east of the Zhe River submitted to Jiangling.", idiomatic: "Thereupon everything east of the Zhe River submitted to Jiangling." },
  { zh: "湘東王繹以靈洗為譙州刺史，領新安太守。", literal: "Prince Yi of Xiangdong made Lingxi Inspector of Qiao and concurrent Administrator of Xin'an.", idiomatic: "Prince Xiao Yi of Xiangdong made Lingxi inspector of Qiao and concurrent administrator of Xin'an." },
  { zh: "十一月，乙亥，王僧辯等復上表勸進，湘東王繹不許。", literal: "In the eleventh month, on yihai, Wang Sengbian and others again submitted a memorial urging accession; Prince Yi of Xiangdong would not consent.", idiomatic: "In the eleventh month, on yihai, Wang Sengbian and others again urged accession; Prince Xiao Yi of Xiangdong would not consent." },
  { zh: "戊寅，繹以湘州刺史安南侯方矩為中衛將軍以自副。", literal: "On wuyin, Yi made Xiangzhou Inspector Marquis Fangju of Annan Central Guard General as his deputy.", idiomatic: "On wuyin, Yi made Xiangzhou inspector Marquis Fangju of Annan his Central Guard General and deputy." },
  { zh: "方矩，方諸之弟也。", literal: "Fangju was Fangzhu's younger brother.", idiomatic: "Fangju was Fangzhu's younger brother." },
  { zh: "以南平王恪為湘州刺史。", literal: "He made Prince Ke of Nanping Inspector of Xiangzhou.", idiomatic: "He made Prince Ke of Nanping inspector of Xiangzhou." },
  { zh: "侯景以趙伯超為東道行台，據錢塘；", literal: "Hou Jing made Zhao Bochao Eastern Route Mobile Headquarters and garrisoned Qiantang.", idiomatic: "Hou Jing made Zhao Bochao eastern-route mobile headquarters and garrisoned Qiantang." },
  { zh: "以田遷為軍司，據富春；", literal: "He made Tian Qian Army Secretary and garrisoned Fuchun.", idiomatic: "He made Tian Qian army secretary and garrisoned Fuchun." },
  { zh: "以李慶緒為中軍都督，謝答仁為右廂都督，李遵為左廂都督，以討劉神茂。", literal: "He made Li Qingxu Commander of the Center Army, Xie Daren Commander of the Right Wing, and Li Zun Commander of the Left Wing, to campaign against Liu Shenma.", idiomatic: "He made Li Qingxu commander of the center army, Xie Daren commander of the right wing, and Li Zun commander of the left wing, to campaign against Liu Shenma." },
  { zh: "己卯，加侯景九錫，漢國置丞相以下官。", literal: "On jimao, Hou Jing was granted the Nine Bestowals; the Han state established offices from Chancellor of State downward.", idiomatic: "On jimao, Hou Jing was granted the Nine Bestowals; the Han state established offices from chancellor of state downward." },
  { zh: "己丑，豫章王棟禪位於景，景即皇帝位於南郊。", literal: "On jichou, Prince Dong of Yuzhang abdicated to Jing; Jing took the imperial throne at the Southern Suburb.", idiomatic: "On jichou, Prince Dong of Yuzhang abdicated to Jing; Jing took the throne at the Southern Suburb." },
  { zh: "還，登太極殿，其黨數萬，皆吹脣呼噪而上。", literal: "Returning, he ascended the Hall of Supreme Pole; his followers, tens of thousands, all pursed their lips and whooped as they went up.", idiomatic: "Returning, he ascended the Hall of Supreme Pole; tens of thousands of his followers pursed their lips and whooped their way up the steps." },
  { zh: "大赦，改元太始。", literal: "A general amnesty was declared and the era name changed to Taishi.", idiomatic: "He declared a general amnesty and changed the era name to Taishi." },
  { zh: "封棟為淮陰王，並其二弟橋、樛同鎖於密室。", literal: "He enfeoffed Dong as Prince of Huaiyin and locked him together with his two younger brothers Qiao and Jiu in a secret chamber.", idiomatic: "He enfeoffed Dong as Prince of Huaiyin and locked him in a secret chamber together with his younger brothers Qiao and Jiu." },
  { zh: "王偉請立七廟，景曰：「何謂七廟？", literal: "Wang Wei asked to establish seven temples; Jing said, \"What are seven temples?", idiomatic: "Wang Wei asked to establish seven ancestral temples; Jing said, \"What are seven temples?" },
  { zh: "」偉曰：「天子祭七世祖考。", literal: "\" Wei said, \"The Son of Heaven sacrifices to seven generations of ancestors.", idiomatic: "\" Wei said, \"The Son of Heaven sacrifices to seven generations of ancestors." },
  { zh: "」並請七世諱，景曰：「前世吾不復記，唯記我父名標；", literal: "\" He also asked for the taboo names of seven generations; Jing said, \"Earlier generations I no longer recall; I only remember my father's name Biao.", idiomatic: "\" He also asked for seven generations of taboo names; Jing said, \"I no longer recall earlier generations; I only remember my father's name, Biao." },
  { zh: "且彼在朔州，那得來啖此！", literal: "Besides, they are in Shuozhou—how could they come eat this!", idiomatic: "Besides, they are in Shuozhou—how could they come here to eat this!" },
  { zh: "」眾咸笑之。", literal: "\" All laughed.", idiomatic: "\" All laughed." },
  { zh: "景黨有知景祖名乙羽周者；", literal: "Among Jing's followers was one who knew his grandfather's name was Yiyuzhou.", idiomatic: "Among Jing's followers was one who knew his grandfather's name was Yiyuzhou." },
  { zh: "自外皆王偉制其名位，追尊父標為元皇帝。", literal: "Apart from that, Wang Wei devised all titles and ranks and posthumously honored his father Biao as Emperor Yuan.", idiomatic: "Otherwise Wang Wei devised every title and rank, and posthumously honored Jing's father Biao as Emperor Yuan." },
  { zh: "景之作相也，以西州為府，文武無尊卑皆引接，及居禁中，非故舊不得見，由是諸將多怨望。", literal: "When Jing was chancellor, he took Xizhou as his headquarters and received civil and military men without regard to rank; once he dwelt within the palace, none but old associates could see him, and many generals nursed resentment.", idiomatic: "As chancellor, Jing had taken Xizhou for his headquarters and received civil and military men without regard to rank; once he lived within the palace, none but old associates could see him, and many generals nursed resentment." },
  { zh: "景好獨乘小馬，彈射飛鳥，王偉每禁止之，不許輕出。", literal: "Jing liked to ride a small horse alone and shoot at flying birds; Wang Wei constantly forbade him and would not allow him out lightly.", idiomatic: "Jing liked to ride out alone on a small horse and shoot at birds; Wang Wei constantly forbade it and would not let him go out lightly." },
  { zh: "景鬱鬱不樂，更成失志，曰：「吾無事為帝，與受擯不殊。", literal: "Jing grew gloomy and joyless, further losing heart, and said, \"I had no business becoming emperor—it differs little from being cast aside.", idiomatic: "Jing grew gloomy and lost heart. \"I had no business becoming emperor,\" he said. \"It differs little from being cast aside." },
  { zh: "壬辰，湘東王以長沙王韶為郢州刺史。", literal: "On renchen, the Prince of Xiangdong made Prince Shao of Changsha Inspector of Yingzhou.", idiomatic: "On renchen, the Prince of Xiangdong made Prince Shao of Changsha inspector of Yingzhou." },
  { zh: "益州長史劉孝勝等勸武陵王紀稱帝，紀雖未許，而大造乘輿車服。", literal: "Liu Xiaosheng, Chief Administrator of Yizhou, and others urged Prince Ji of Wuling to declare himself emperor; though Ji did not yet consent, he greatly made imperial carriages and regalia.", idiomatic: "Chief Administrator Liu Xiaosheng of Yizhou and others urged Prince Ji of Wuling to declare himself emperor; though Ji had not yet consented, he was already building imperial carriages and regalia on a grand scale." },
  { zh: "十二月，丁未，謝答仁、李慶緒攻建德，擒元頵、李占送建康，景截其手足以徇，經日乃死。", literal: "In the twelfth month, on dingwei, Xie Daren and Li Qingxu attacked Jiande, captured Yuan Yun and Li Zhan, and sent them to Jiankang; Jing cut off their hands and feet to display as warning, and after a full day they died.", idiomatic: "In the twelfth month, on dingwei, Xie Daren and Li Qingxu attacked Jiande, captured Yuan Yun and Li Zhan, and sent them to Jiankang; Jing cut off their hands and feet for public display, and after a full day they died." },
  { zh: "齊主每出入，常以中山王自隨，王妃太原公主恆為之嘗飲食，護視之。", literal: "Whenever the Qi emperor went in or out, he always had the Prince of Zhongshan accompany him; the Princess of Taiyuan, his consort, constantly tasted his food and drink and watched over him.", idiomatic: "Whenever the Qi emperor went in or out, the Prince of Zhongshan always accompanied him; the Princess of Taiyuan, his consort, constantly tasted his food and drink and watched over him." },
  { zh: "是月，齊主飲公主酒，使人鴆中山王，殺之，並其三子，謚王曰魏孝靜皇帝，葬於鄴西漳北。", literal: "That month the Qi emperor made the princess drink wine, then had men poison the Prince of Zhongshan and killed him together with his three sons; he gave the prince the posthumous title Emperor Xiaojing of Wei and buried him north of the Zhang west of Ye.", idiomatic: "That month the Qi emperor made the princess drink, then had the Prince of Zhongshan poisoned and killed him together with his three sons; he gave the prince the posthumous title Emperor Xiaojing of Wei and buried him north of the Zhang west of Ye." },
  { zh: "其後齊主忽掘其陵，投梓宮於漳水。", literal: "Later the Qi emperor suddenly opened his tomb and cast the outer coffin into the Zhang waters.", idiomatic: "Later the Qi emperor suddenly opened the tomb and threw the outer coffin into the Zhang." },
  { zh: "齊主初受禪，魏神主悉寄於七帝寺，至是，亦取焚之。", literal: "When the Qi emperor first received the abdication, all Wei spirit tablets had been lodged at the Temple of Seven Emperors; now he took them out and burned them as well.", idiomatic: "When the Qi emperor first received the abdication, all Wei spirit tablets had been lodged at the Temple of Seven Emperors; now he took them out and burned them too." },
  { zh: "彭城公元韶以高氏婿，寵遇異於諸元。", literal: "Yuan Shao, Prince of Pengcheng, as a son-in-law of the Gao clan, received favor unlike other members of the Yuan.", idiomatic: "Yuan Shao, Prince of Pengcheng, as a son-in-law of the Gao clan, received favor unlike the other Yuans." },
  { zh: "開府儀同三司美陽公元暉業以位望隆重，又志氣不倫，尤為齊主所忌，從齊主在晉陽。", literal: "Palace Gate Commander of the First Rank Yuan Huiye of Meiyang, by rank and repute weighty and by temperament out of the common run, was especially feared by the Qi emperor and accompanied him at Jinyang.", idiomatic: "Palace Gate Commander of the First Rank Yuan Huiye of Meiyang, weighty in rank and repute and odd in temperament, was especially feared by the Qi emperor and accompanied him at Jinyang." },
  { zh: "暉業於宮門外罵韶曰：「爾不及一老嫗，負璽與人。", literal: "At the palace gate Huiye cursed Shao, saying, \"You are not the equal of an old woman, bearing the seal and giving it to another.", idiomatic: "At the palace gate Huiye cursed Shao: \"You are not the equal of an old woman—bearing the imperial seal and handing it to another." },
  { zh: "何不擊碎之！", literal: "Why not smash it to pieces!", idiomatic: "Why not smash it to pieces!" },
  { zh: "我出此言，知即死，爾亦詎得幾時！", literal: "I speak thus knowing I shall die at once—you too, how much longer have you?", idiomatic: "I speak thus knowing I die at once—you too, how much longer have you?" },
  { zh: "」齊主聞而殺之，及臨淮公元孝友，皆鑿汾水冰，沉其屍。", literal: "\" The Qi emperor heard and killed him, and Yuan Xiaoyou of Linhuai as well; all were cut through the ice of the Fen River and their bodies sunk.", idiomatic: "\" The Qi emperor heard and killed him, and Yuan Xiaoyou of Linhuai as well; all were cut through the ice of the Fen and their bodies sunk." },
  { zh: "孝友，彧之弟也。", literal: "Xiaoyou was Yu's younger brother.", idiomatic: "Xiaoyou was Yu's younger brother." },
  { zh: "齊主嘗剃元韶鬢鬚，加之粉黛以自隨，曰：「吾以彭城為嬪御。", literal: "The Qi emperor once shaved Yuan Shao's temples and beard, applied powder and rouge, and kept him at his side, saying, \"I take Pengcheng as my palace woman.", idiomatic: "The Qi emperor once shaved Yuan Shao's temples and beard, applied powder and rouge, and kept him at his side, saying, \"I take Pengcheng as my palace woman." },
  { zh: "」言其懦弱如婦人也。", literal: "\" He meant that Shao was timid as a woman.", idiomatic: "\" He meant that Shao was timid as a woman." },
  { zh: "世祖孝元皇帝上承聖元年（", literal: "Shizu, Emperor Xiaoyuan, first year of Chengsheng (", idiomatic: "Shizu, Emperor Xiaoyuan, first year of Chengsheng (" },
  { zh: "壬申，公元五五二年）", literal: "renshen, AD 552)", idiomatic: "renshen, AD 552)" },
  { zh: "春，正月，湘東王以南平內史王褒為吏部尚書。", literal: "In spring, the first month, the Prince of Xiangdong made Wang Bao, Administrator of Nanping, Minister of Personnel.", idiomatic: "In spring, the first month, the Prince of Xiangdong made Wang Bao, administrator of Nanping, Minister of Personnel." },
  { zh: "褒，騫之孫也。", literal: "Bao was Qian's grandson.", idiomatic: "Bao was Qian's grandson." },
  { zh: "齊人屢侵侯景邊地，甲戌，景遣郭元建帥步軍趣小峴，侯子鑒帥舟師向濡須，己卯，至合肥；", literal: "Qi men repeatedly raided Hou Jing's borderlands; on jiaxu, Jing sent Guo Yuanjian leading infantry toward Xiaoxian and Hou Zijian leading the fleet toward Ruxu; on jimao they reached Hefei.", idiomatic: "Qi forces repeatedly raided Hou Jing's borders; on jiaxu, Jing sent Guo Yuanjian with infantry toward Xiaoxian and Hou Zijian with the fleet toward Ruxu; on jimao they reached Hefei." },
  { zh: "齊人閉城不出，乃引還。", literal: "The Qi men shut the city and would not come out, so they withdrew.", idiomatic: "The Qi shut the city and would not come out, so they withdrew." },
  { zh: "丙申，齊主伐庫莫奚，大破之，俘獲四千人，雜畜十餘萬。", literal: "On bingshen, the Qi emperor campaigned against the Kumo Xi and routed them, capturing four thousand men and more than a hundred thousand head of mixed livestock.", idiomatic: "On bingshen, the Qi emperor campaigned against the Kumo Xi and routed them, capturing four thousand men and more than a hundred thousand head of livestock." },
  { zh: "齊主連年出塞，給事中兼中書舍人唐邕練習軍書，自督將以降勞效本末及四方軍士強弱多少，番代往還，器械精粗，糧儲虛實，靡不諳悉。", literal: "The Qi emperor campaigned beyond the frontier year after year; Attendant Within the Yellow Gates and concurrent Palace Secretary Tang Yong mastered military documents; from commanders downward, the roots and branches of merit, the strength and numbers of troops in every quarter, rotations coming and going, the fineness of weapons, the fullness or emptiness of grain stores—none escaped his knowledge.", idiomatic: "The Qi emperor campaigned beyond the frontier year after year; Attendant Within the Yellow Gates and concurrent Palace Secretary Tang Yong mastered the military rolls—from commanders down, who had earned what, how strong every army in every quarter was, who rotated where, which weapons were fine or crude, which granaries full or empty; nothing escaped him." },
  { zh: "或於帝前簡閱，雖數千人，不執文簿，唱其姓名，未嘗謬誤。", literal: "Sometimes before the emperor he would review troops; though they numbered thousands, without holding a register he would call out names and never err.", idiomatic: "Sometimes before the emperor he reviewed troops; though they numbered thousands, without a register he called out names and never erred." },
  { zh: "帝常曰：「唐邕強幹，一人當千。", literal: "The emperor often said, \"Tang Yong is forceful and capable—one man equals a thousand.", idiomatic: "The emperor often said, \"Tang Yong is forceful and capable—one man equals a thousand." },
  { zh: "」又曰：「邕每有軍事，手作文書，口且處分，耳又聽受，實異人也！", literal: "\" He also said, \"Whenever there is military business, Yong writes documents by hand, gives orders by mouth, and listens with his ears at the same time—truly a strange man!", idiomatic: "\" He also said, \"Whenever there is military business, Yong writes with his hands, gives orders with his mouth, and listens with his ears at once—truly a strange man!" },
  { zh: "」寵待賞賜，群臣莫及。", literal: "\" Favor, rewards, and gifts—no minister could match him.", idiomatic: "\" In favor and reward, no minister could match him." },
  { zh: "魏將王雄取上津、魏興，東梁州刺史安康李遷哲軍敗。", literal: "Wei general Wang Xiong took Shangjin and Weixing; Li Qianzhe of Ankang, Eastern Liangzhou Inspector, was defeated.", idiomatic: "Wei general Wang Xiong took Shangjin and Weixing; Li Qianzhe of Ankang, Eastern Liangzhou inspector, was defeated." },
  { zh: "降之。", literal: "He surrendered to him.", idiomatic: "Qianzhe surrendered." },
  { zh: "突闕土門襲擊柔然，大破之。", literal: "Tujue's Tumen struck Rouran and routed them.", idiomatic: "Tumen of the Turks struck Rouran and routed them." },
  { zh: "柔然頭兵可汗自殺，其太子庵羅辰及阿那瑰從弟登注俟利、登注子庫提並帥眾奔齊，餘眾復立登注次子鐵伐為主。", literal: "Rouran's Khan Toubing killed himself; his crown prince Anluochen and Anagui's younger cousin Dengzhu Sili and Dengzhu's son Kuti all led their followers to flee to Qi; the remainder again made Dengzhu's second son Tiefa their lord.", idiomatic: "Rouran's Khan Toubing killed himself; Crown Prince Anluochen, Anagui's younger cousin Dengzhu Sili, and Dengzhu's son Kuti all led their followers to Qi; the remainder again made Dengzhu's second son Tiefa their lord." },
  { zh: "土門自號伊利可汗，號其妻為可賀敦，子弟謂之特勒，別將兵者皆謂之設。", literal: "Tumen styled himself Yili Khagan, called his wife Khehedun, termed his sons and younger brothers tejin, and termed all who separately commanded troops she.", idiomatic: "Tumen styled himself Yili Khagan, called his wife Khehedun, termed his sons and younger brothers tejin, and termed all who separately commanded troops she." },
  { zh: "湘東王命王僧辯等東擊侯景。", literal: "The Prince of Xiangdong ordered Wang Sengbian and others east to strike Hou Jing.", idiomatic: "The Prince of Xiangdong ordered Wang Sengbian and others east against Hou Jing." },
  { zh: "二月，庚子，諸軍發尋陽，舳艫數百里。", literal: "In the second month, on gengzi, the armies set out from Xunyang; the line of ships stretched for hundreds of li.", idiomatic: "In the second month, on gengzi, the armies set out from Xunyang; the line of ships stretched for hundreds of li." },
  { zh: "陳霸先帥甲士三萬，舟艦二千，自南江出湓口，會僧辯於白茅灣，築壇歃血，共讀盟文，流涕慷慨。", literal: "Chen Baxian led thirty thousand armored men and two thousand vessels from the Southern River out through Pankou, met Sengbian at Baimao Bay, built an altar and smeared blood, together read the covenant text, and wept with fervor.", idiomatic: "Chen Baxian led thirty thousand armored men and two thousand vessels from the Southern River out through Pankou, met Sengbian at Baimao Bay, built an altar and smeared blood, read the covenant together, and wept with fervor." },
  { zh: "癸卯，僧辯使侯瑱南陵、鵲頭二戍，克之。", literal: "On guimao, Sengbian sent Hou Tian against the garrisons of Nanling and Quetou and took them.", idiomatic: "On guimao, Sengbian sent Hou Tian against the garrisons of Nanling and Quetou and took them." },
  { zh: "戊申，僧辯等軍於大雷；", literal: "On wushen, Sengbian and others encamped at Dalei.", idiomatic: "On wushen, Sengbian and others encamped at Dalei." },
  { zh: "丙辰，發鵲頭。", literal: "On bingchen, they set out from Quetou.", idiomatic: "On bingchen, they set out from Quetou." },
  { zh: "戊午，侯子鑒還至戰鳥，西軍奄至，子鑒驚懼，奔還淮南。", literal: "On wuwu, Hou Zijian returned to Zhanniao; the western army came upon him suddenly; Zijian, alarmed and afraid, fled back to Huainan.", idiomatic: "On wuwu, Hou Zijian returned to Zhanniao; the western army came upon him suddenly; terrified, Zijian fled back to Huainan." },
  { zh: "侯景儀同三司謝答仁攻劉神茂於東陽，程靈洗、張彪皆勒兵將救之，神茂欲專其功，不許，營於下淮。", literal: "Hou Jing's Palace Attendant of the Third Rank Xie Daren attacked Liu Shenma at Dongyang; Cheng Lingxi and Zhang Biao both mustered troops to rescue him; Shenma wished to keep the merit for himself and would not allow it, and encamped at Xiahuai.", idiomatic: "Hou Jing's Palace Attendant of the Third Rank Xie Daren attacked Liu Shenma at Dongyang; Cheng Lingxi and Zhang Biao both mustered troops to rescue him; Shenma wanted the credit alone and refused them, encamping at Xiahuai." },
  { zh: "或謂神茂曰：「賊長於野戰，下淮地平，四面受敵，不如據七里瀨，賊必不能進。", literal: "Someone told Shenma, \"The rebels excel at field battle; Xiahuai is level ground and exposed on every side—better hold Qililai; the rebels surely cannot advance.", idiomatic: "Someone told Shenma, \"The rebels excel in open battle; Xiahuai is level and exposed on every side—better hold Qililai; they cannot advance there." },
  { zh: "」不從。", literal: "\" He would not heed this.", idiomatic: "\" He would not listen." },
  { zh: "神茂偏裨多北人，不與神茂同心，別將王曄、酈通並據外營，降於答仁，劉歸義、尹思合等棄城走。", literal: "Many of Shenma's subordinate commanders were northerners and did not share his heart; detached commanders Wang Ye and Li Tong both held the outer camp and surrendered to Daren; Liu Guiyi, Yin Sihe, and others abandoned the city and fled.", idiomatic: "Many of Shenma's subordinate commanders were northerners and did not share his heart; detached commanders Wang Ye and Li Tong held the outer camp and surrendered to Daren; Liu Guiyi, Yin Sihe, and others abandoned the city and fled." },
  { zh: "神茂孤危，辛未，亦降於答仁，答仁送之建康。", literal: "Shenma, isolated and endangered, on xinwei also surrendered to Daren; Daren sent him to Jiankang.", idiomatic: "Isolated and desperate, Shenma on xinwei also surrendered to Daren, who sent him to Jiankang." },
  { zh: "癸酉，王僧辯等至蕪湖，侯景守將張黑棄城走。", literal: "On guiyou, Wang Sengbian and others reached Wuhu; Hou Jing's garrison commander Zhang Hei abandoned the city and fled.", idiomatic: "On guiyou, Wang Sengbian and others reached Wuhu; Hou Jing's garrison commander Zhang Hei abandoned the city and fled." },
  { zh: "景聞之，甚懼，下詔赦湘東王繹、王僧辯之罪，眾鹹笑之。", literal: "Jing heard this and was greatly afraid; he issued an edict pardoning Prince Yi of Xiangdong and Wang Sengbian; all laughed.", idiomatic: "Jing heard and was greatly afraid; he issued an edict pardoning Prince Xiao Yi of Xiangdong and Wang Sengbian; everyone laughed." },
  { zh: "侯子鑒據姑孰南洲以拒西師，景遣其黨史安和等將兵二千助之。", literal: "Hou Zijian held Gudu's southern isle to resist the western army; Jing sent his follower Shi Anhe and others with two thousand troops to assist him.", idiomatic: "Hou Zijian held Gudu's southern isle against the western army; Jing sent his follower Shi Anhe and others with two thousand men to help." },
  { zh: "三月，己巳朔，景下詔欲自至姑孰，又遣人戒子鑒曰：「西人善水戰，勿與爭鋒；", literal: "In the third month, on the first day jisi, Jing issued an edict saying he wished to go to Gudu himself, and also sent men to warn Zijian, \"The westerners excel at naval combat—do not contend with them at the sharp edge.", idiomatic: "In the third month, on the first day jisi, Jing issued an edict that he would go to Gudu himself, and sent men to warn Zijian: \"The westerners excel at naval combat—do not meet them on the water." },
  { zh: "往年任約之敗，良為此也。", literal: "Ren Yue's defeat in former years was truly because of this.", idiomatic: "Ren Yue's defeat in former years was exactly because of this." },
  { zh: "若得步騎一交，必當可破，汝但結營岸上，引船入浦以待之。", literal: "If you can get one clash of infantry and cavalry, they can surely be broken; you need only build camps on shore and draw the ships into creeks to await them.", idiomatic: "Give them one clash of infantry and cavalry and they can be broken; you need only build camps on shore and draw the ships into creeks to wait." },
  { zh: "」子鑒乃捨舟登岸，閉營不出。", literal: "\" Zijian then abandoned the boats and went ashore, shut his camps, and would not come out.", idiomatic: "\" Zijian abandoned the boats, went ashore, shut his camps, and would not come out." },
  { zh: "僧辯等停軍蕪湖十餘日，景黨大喜，告景曰：「西師畏吾之強，勢將遁矣，不擊，且失之。", literal: "Sengbian and others halted at Wuhu for more than ten days; Jing's followers were greatly pleased and told Jing, \"The western army fears our strength and is about to flee—if we do not strike, we shall lose them.", idiomatic: "Sengbian halted at Wuhu for more than ten days; Jing's followers rejoiced and told him, \"The western army fears our strength and is about to flee—if we do not strike, we lose them." },
  { zh: "」景乃覆命子鑒為水戰之備。", literal: "\" Jing then countermanded and ordered Zijian to prepare for naval battle.", idiomatic: "\" Jing countermanded and ordered Zijian to prepare for naval battle." },
  { zh: "丁丑，僧辯至姑孰，子鑒帥步騎萬餘人度洲，於岸挑戰，又以□鳥□了千艘載戰士。", literal: "On dingchou, Sengbian reached Gudu; Zijian led more than ten thousand infantry and cavalry across the isle and challenged from the bank, and also had □鳥□了 a thousand vessels carry warriors.", idiomatic: "On dingchou, Sengbian reached Gudu; Zijian led more than ten thousand infantry and cavalry across the isle and challenged from the bank, and also had □鳥□了 a thousand vessels carry warriors." },
  { zh: "僧辯麾細船皆令退縮，留大艦夾泊兩岸。", literal: "Sengbian ordered all light boats to withdraw, leaving great ships moored on both banks.", idiomatic: "Sengbian ordered the light boats to withdraw, leaving great ships moored on both banks." },
  { zh: "子鑒之眾謂水軍欲退，爭出趨之；", literal: "Zijian's men thought the fleet meant to retreat and all rushed out to pursue.", idiomatic: "Zijian's men thought the fleet was retreating and rushed out in pursuit." },
  { zh: "大艦斷其歸路，鼓噪大呼，合戰中江，子鑒大敗，士卒赴水死者數千人。", literal: "The great ships cut off their return; drums and shouts rose; battle joined mid-river; Zijian was utterly defeated and thousands of soldiers died in the water.", idiomatic: "The great ships cut off their return; drums and shouts rose; battle joined mid-river; Zijian was routed and thousands drowned." },
  { zh: "子鑒僅以身免，收散卒走還建康，據東府。", literal: "Zijian barely escaped with his life, gathered scattered troops, fled back to Jiankang, and held the Eastern Palace.", idiomatic: "Zijian barely escaped, gathered scattered troops, fled to Jiankang, and held the Eastern Palace." },
  { zh: "僧辯留虎臣將軍莊丘慧達鎮姑孰，引軍而前，歷陽戍迎降。", literal: "Sengbian left Tiger-Minister General Zhuangqiu Huida to garrison Gudu and led the army forward; the garrison of Liyang came out to surrender.", idiomatic: "Sengbian left Tiger-Minister General Zhuangqiu Huida at Gudu and advanced; the garrison of Liyang surrendered." },
  { zh: "景聞子鑒敗，大懼，涕下覆面，引衾而臥，良久方起，歎曰：「誤殺乃公！", literal: "Jing heard that Zijian was defeated and was greatly afraid; tears covered his face; he pulled the quilt over himself and lay down; only after a long while did he rise and sigh, \"I killed the old man by mistake!", idiomatic: "Hearing of Zijian's defeat, Jing was terrified; tears covered his face; he pulled the quilt over himself and lay down; only after a long while did he rise and sigh, \"I killed the old man by mistake!" },
  { zh: "庚辰，僧辯督諸軍至張公洲，辛巳，乘潮入淮，進至禪靈寺前。", literal: "On gengchen, Sengbian directed the armies to Zhanggong Isle; on xinsi, riding the tide they entered the Huai and advanced to before Chanling Temple.", idiomatic: "On gengchen, Sengbian brought the armies to Zhanggong Isle; on xinsi, riding the tide they entered the Huai and advanced to Chanling Temple." },
  { zh: "景召石頭津主張賓，使引淮中□叉□步及海艟，以石縋之，塞淮口；", literal: "Jing summoned Zhang Bin, master of the Shitou ford, and had him bring □叉□步 from the Huai and sea warships, sink them with stones, and block the Huai mouth.", idiomatic: "Jing summoned Zhang Bin, master of the Shitou ford, had him bring □叉□步 from the Huai and sea warships, sink them with stones, and block the Huai mouth." },
  { zh: "緣淮作城，自石頭至於朱雀街，十餘里中，樓堞相接。", literal: "Along the Huai he built a wall; from Shitou to Zhuque Street, for more than ten li, towers and battlements linked one to another.", idiomatic: "Along the Huai he built a wall from Shitou to Zhuque Street; for more than ten li, towers and battlements linked end to end." },
  { zh: "僧辯問計於陳霸先，霸先曰：「前柳仲禮數十萬兵隔水而坐，韋粲在青溪，竟不度岸，賊登高望之，表裡俱盡，故能覆我師徒。", literal: "Sengbian asked Chen Baxian for counsel; Baxian said, \"Before, Liu Zhongli with hundreds of thousands of men sat across the water, Wei Can was at Qingxi, and in the end they never crossed the bank; the rebels looked down from the heights and saw inside and out completely, and so could overturn our army.", idiomatic: "Sengbian asked Chen Baxian for counsel; Baxian said, \"Before, Liu Zhongli sat across the water with hundreds of thousands of men, Wei Can was at Qingxi, and neither crossed the bank; the rebels looked down and saw everything inside and out, and overturned our army." },
  { zh: "今圍石頭，須度北岸。", literal: "Now besieging Shitou, we must cross the north bank.", idiomatic: "Now, besieging Shitou, we must cross the north bank." },
  { zh: "諸將若不能當鋒，霸先請先往立柵。", literal: "If the generals cannot meet the sharp edge, Baxian asks to go first and build palisades.", idiomatic: "If the generals cannot meet the charge, Baxian asks to go first and build palisades." },
  { zh: "」壬午，霸先於石頭西落星山築柵，眾軍次連八城，直出石頭西北。", literal: "\" On renwu, Baxian built palisades at Luoxing Mountain west of Shitou; the armies in succession linked eight forts and thrust straight out northwest of Shitou.", idiomatic: "\" On renwu, Baxian built palisades at Luoxing Mountain west of Shitou; the armies linked eight forts in succession and thrust out northwest of Shitou." },
  { zh: "景恐西州路絕，自帥侯子鑒等亦於石頭東北築五城以遏大路。", literal: "Jing, fearing the Xizhou road would be cut, himself led Hou Zijian and others to build five forts northeast of Shitou to block the great road.", idiomatic: "Fearing the Xizhou road would be cut, Jing himself led Hou Zijian and others to build five forts northeast of Shitou and block the great road." },
  { zh: "景使王偉等守台城。", literal: "Jing sent Wang Wei and others to guard the palace city.", idiomatic: "Jing sent Wang Wei and others to guard the palace city." },
  { zh: "乙酉，景殺湘東王世子方諸、前平東將軍杜幼安。", literal: "On yiyou, Jing killed Prince Yi of Xiangdong's heir Fangzhu and former General Who Pacifies the East Du You'an.", idiomatic: "On yiyou, Jing killed Prince Xiao Yi's heir Fangzhu and former General Who Pacifies the East Du You'an." },
  { zh: "劉神茂至建康，丙戌，景命為大坐刀碓，先進其足，寸寸斬之，以至於頭。", literal: "Liu Shenma reached Jiankang; on bingxu, Jing ordered the great seated blade and pestle; they advanced his feet first and chopped him inch by inch up to the head.", idiomatic: "Liu Shenma reached Jiankang; on bingxu, Jing ordered the great seated blade and pestle; they fed in his feet first and chopped him inch by inch up to the head." },
  { zh: "留異外同神茂而潛通於景，故得免禍。", literal: "Liu Yi outwardly joined Shenma but secretly communicated with Jing, and so escaped disaster.", idiomatic: "Liu Yi outwardly joined Shenma but secretly dealt with Jing, and so escaped punishment." },
  { zh: "丁亥，王僧辯進軍招提寺北，侯景帥眾萬餘人、鐵騎八百餘匹陳於西州之西。", literal: "On dinghai, Wang Sengbian advanced north of Zhaoti Temple; Hou Jing led more than ten thousand men and more than eight hundred iron cavalry and formed battle lines west of Xizhou.", idiomatic: "On dinghai, Wang Sengbian advanced north of Zhaoti Temple; Hou Jing drew up more than ten thousand men and eight hundred iron cavalry west of Xizhou." },
  { zh: "陳霸先曰：「我眾賊寡，應分其兵勢，以強制弱；", literal: "Chen Baxian said, \"We are many and the rebels few—we should divide their military force and use strength to constrain weakness.", idiomatic: "Chen Baxian said, \"We are many and they few—we should divide their force and use strength against weakness." },
  { zh: "何故聚其鋒銳，令致死於我！", literal: "Why gather their sharp edge and make them fight to the death against us!", idiomatic: "Why gather their best troops and make them fight to the death against us!" },
  { zh: "」乃命諸將分處置兵。", literal: "\" He then ordered the generals to deploy troops in separate positions.", idiomatic: "\" He then ordered the generals to deploy in separate positions." },
  { zh: "景衝將軍王僧志陳，僧志小縮，霸先遣將軍安陸徐度將弩手二千橫截其後，景兵乃卻。", literal: "Jing's assault general Wang Sengzhi formed battle lines; Sengzhi shrank back slightly; Baxian sent General Xu Du of Anlu with two thousand crossbowmen to cut across their rear, and Jing's troops then withdrew.", idiomatic: "Jing's assault general Wang Sengzhi formed up; Sengzhi faltered; Baxian sent General Xu Du of Anlu with two thousand crossbowmen to cut their rear, and Jing's troops withdrew." },
  { zh: "霸先與王琳、杜龕等以鐵騎乘之，僧辯以大軍繼進，景兵敗退，據其柵。", literal: "Baxian with Wang Lin, Du Kan, and others charged with iron cavalry; Sengbian followed with the great army; Jing's troops were defeated and withdrew to their palisades.", idiomatic: "Baxian with Wang Lin, Du Kan, and others charged with iron cavalry; Sengbian followed with the main army; Jing's troops fell back to their palisades." },
  { zh: "龕，岸之兄子也。", literal: "Kan was An's elder brother's son.", idiomatic: "Kan was An's nephew." },
  { zh: "景儀同三司盧暉略守石頭城，開北門降，僧辯入據之。", literal: "Jing's Palace Attendant of the Third Rank Lu Huiyue guarded Shitou city, opened the north gate and surrendered; Sengbian entered and took it.", idiomatic: "Jing's Palace Attendant of the Third Rank Lu Huiyue held Shitou, opened the north gate and surrendered; Sengbian entered and took it." },
  { zh: "景與霸先殊死戰，景帥百餘騎，棄槊執刀，左右衝陳。", literal: "Jing fought Baxian to the death; Jing led more than a hundred horsemen, cast aside his spear and took a blade, and charged left and right through the lines.", idiomatic: "Jing fought Baxian to the death; leading more than a hundred horsemen, he cast aside his spear, took a blade, and charged left and right through the lines." },
  { zh: "陳不動，眾遂大潰，諸軍逐北至西明門。", literal: "The lines did not break; his host then collapsed in great rout; the armies pursued north to Ximing Gate.", idiomatic: "The lines held; his host collapsed; the armies pursued to Ximing Gate." },
  { zh: "景至闕下，不敢入台，召王偉責之曰：「爾令我為帝，今日誤我！", literal: "Jing reached the gate-towers but dared not enter the palace; he summoned Wang Wei and reproached him, saying, \"You made me emperor—today you have ruined me!", idiomatic: "Jing reached the gate-towers but dared not enter the palace; he summoned Wang Wei and said, \"You made me emperor—you have ruined me today!" },
  { zh: "」偉不能對，繞闕而藏。", literal: "\" Wei could not answer and circled the gate-towers hiding.", idiomatic: "\" Wei could not answer and hid circling the gate-towers." },
  { zh: "景欲走，偉執鞚諫曰：「自古豈有叛天子邪！", literal: "Jing wished to flee; Wei seized his bridle and remonstrated, \"Since antiquity has there ever been one who betrayed the Son of Heaven?", idiomatic: "Jing wished to flee; Wei seized his bridle: \"Since antiquity, has anyone betrayed the Son of Heaven?" },
  { zh: "宮中衛士，猶足一戰，棄此，將欲安之？", literal: "The palace guards are still enough for one battle—abandon this, and where will you go?", idiomatic: "The palace guards are still enough for one battle—abandon this, and where will you go?" },
  { zh: "」景曰：「我昔敗賀拔勝，破葛榮，揚名河、朔，度江平台城，降柳仲禮如反掌；", literal: "\" Jing said, \"I once defeated Heba Sheng, broke Ge Rong, made my name on the Yellow and the north, crossed the river and took the palace city, and reduced Liu Zhongli as easily as turning my palm.", idiomatic: "\" Jing said, \"I once defeated Heba Sheng, broke Ge Rong, made my name on the Yellow and the north, crossed the river and took the palace city, and reduced Liu Zhongli as easily as turning my palm." },
  { zh: "今日天亡我也！", literal: "Today Heaven destroys me!", idiomatic: "Today Heaven destroys me!" },
  { zh: "」因仰觀石闕，歎息久之。", literal: "\" He then looked up at the stone gate-towers and sighed for a long while.", idiomatic: "\" He looked up at the stone gate-towers and sighed for a long while." },
  { zh: "以皮囊盛其江東所生二子，掛之鞍後，與房世貴等百餘騎東走，欲就謝答仁於吳。", literal: "He put his two sons born east of the river into leather sacks and hung them behind his saddle; with Fang Shigui and more than a hundred horsemen he fled east, intending to join Xie Daren in Wu.", idiomatic: "He put his two sons born east of the river into leather sacks and hung them behind his saddle; with Fang Shigui and more than a hundred horsemen he fled east toward Xie Daren in Wu." },
  { zh: "侯子鑒、王偉、陳慶奔朱方。", literal: "Hou Zijian, Wang Wei, and Chen Qing fled to Zhufang.", idiomatic: "Hou Zijian, Wang Wei, and Chen Qing fled to Zhufang." },
  { zh: "僧辯命裴之橫、杜龕屯杜姥宅，杜崱入據台城。", literal: "Sengbian ordered Pei Zhiheng and Du Kan to encamp at Old Lady Du's residence; Du Ya entered and took the palace city.", idiomatic: "Sengbian ordered Pei Zhiheng and Du Kan to encamp at Old Lady Du's residence; Du Ya entered and took the palace city." },
  { zh: "僧辯不戢軍士，剽掠居民。", literal: "Sengbian did not restrain his soldiers; they plundered the people.", idiomatic: "Sengbian did not restrain his soldiers; they plundered the people." },
  { zh: "男女裸露，自石頭至於東城，號泣滿道。", literal: "Men and women stripped bare; from Shitou to the eastern city, wailing filled the roads.", idiomatic: "Men and women stripped bare; from Shitou to the eastern city, wailing filled the roads." },
  { zh: "是夜，軍士遺火。", literal: "That night soldiers left fire behind.", idiomatic: "That night soldiers set fires." },
  { zh: "焚太極殿及東西堂，寶器、羽儀、輦輅無遺。", literal: "The Hall of Supreme Pole and the eastern and western halls were burned; treasures, feather regalia, and imperial carriages—nothing remained.", idiomatic: "The Hall of Supreme Pole and the eastern and western halls burned; treasures, feather regalia, and imperial carriages—nothing remained." },
  { zh: "戊子，僧辯命侯瑱等帥精甲五千追景。", literal: "On wuzi, Sengbian ordered Hou Tian and others to lead five thousand picked armored men in pursuit of Jing.", idiomatic: "On wuzi, Sengbian ordered Hou Tian and others to pursue Jing with five thousand picked armored men." },
  { zh: "王克、元羅等帥台內舊臣迎僧辯於道，僧辯勞克曰：「甚苦，事夷狄之君。", literal: "Wang Ke, Yuan Luo, and others led the old ministers within the palace to welcome Sengbian on the road; Sengbian comforted Ke, saying, \"You have suffered greatly, serving a barbarian lord.", idiomatic: "Wang Ke, Yuan Luo, and others led the old palace ministers to welcome Sengbian on the road; Sengbian said to Ke, \"You have suffered greatly, serving a barbarian lord." },
  { zh: "」克不能對。", literal: "\" Ke could not answer.", idiomatic: "\" Ke could not answer." },
  { zh: "又問：「璽紱何在？", literal: "He asked again, \"Where are the seal and cord?", idiomatic: "He asked again, \"Where are the seal and cord?" },
  { zh: "」克良久曰：「趙平原持去。", literal: "\" After a long while Ke said, \"Zhao Pingyuan took them away.", idiomatic: "\" After a long while Ke said, \"Zhao Pingyuan took them." },
  { zh: "」僧辯曰：「王氏百世卿族，一朝而墜。", literal: "\" Sengbian said, \"The Wang clan, a hundred generations of ministerial houses, in one morning fell.", idiomatic: "\" Sengbian said, \"The Wang clan—a hundred generations of ministerial houses—in one morning fell." },
  { zh: "」僧辯迎太宗梓宮升朝堂，帥百官哭踴如禮。", literal: "\" Sengbian welcomed Emperor Taizong's outer coffin up to the audience hall and led the hundred officials in weeping and stamping according to rite.", idiomatic: "\" Sengbian brought Emperor Taizong's outer coffin to the audience hall and led the hundred officials in the prescribed mourning." },
  { zh: "己丑，僧辯等上表勸進，且迎都建業。", literal: "On jichou, Sengbian and others submitted a memorial urging accession and also invited the capital to be moved to Jianye.", idiomatic: "On jichou, Sengbian and others urged accession and invited the capital to Jianye." },
  { zh: "湘東王答曰：「淮海長鯨，雖雲授首；", literal: "The Prince of Xiangdong replied, \"The long whale of Huaihai, though said to have surrendered its head.", idiomatic: "The Prince of Xiangdong replied, \"The long whale of Huaihai, though said to have lost its head." },
  { zh: "襄陽短狐，未全革面。", literal: "The short fox of Xiangyang has not yet fully changed its face.", idiomatic: "The short fox of Xiangyang has not yet fully changed its face." },
  { zh: "太平玉燭，爾乃議之。", literal: "The jade candle of great peace—only then discuss it.", idiomatic: "The jade candle of great peace—only then shall we discuss it." },
  { zh: "庚寅，南兗州刺史郭元建、秦郡戍主郭正買、陽平戍主魯伯和、行南徐州事郭子仲，並據城降。", literal: "On gengyin, Southern Yanzhou Inspector Guo Yuanjian, Qin commandery garrison commander Guo Zhengmai, Yangping garrison commander Lu Bohe, and acting Southern Xuzhou administrator Guo Zizhong all held their cities and surrendered.", idiomatic: "On gengyin, Southern Yanzhou inspector Guo Yuanjian, Qin commandery garrison commander Guo Zhengmai, Yangping garrison commander Lu Bohe, and acting Southern Xuzhou administrator Guo Zizhong all surrendered their cities." },
  { zh: "僧辯之發江陵也，啟湘東王曰：「平賊之後，嗣君萬福，未審何以為禮？", literal: "When Sengbian set out from Jiangling, he memorialized the Prince of Xiangdong, saying, \"After the rebels are pacified, may the heir enjoy ten thousand blessings—but I do not know what rites should be used?", idiomatic: "When Sengbian set out from Jiangling, he wrote the Prince of Xiangdong: \"After the rebels are pacified, may the heir live in ten thousand blessings—but what rites should be used?" },
  { zh: "」王曰：「六門之內，自極兵威。", literal: "\" The prince said, \"Within the six gates, apply military authority to the utmost.", idiomatic: "\" The prince said, \"Within the six gates, apply military authority to the utmost." },
  { zh: "」僧辯曰：「討賊之謀，臣為己任，成濟之事，請別舉人。", literal: "\" Sengbian said, \"The plan to destroy the rebels is my own charge; the matter of Cheng Ji, please choose another man.", idiomatic: "\" Sengbian said, \"The plan to destroy the rebels is mine; the matter of Cheng Ji, choose another man." },
  { zh: "」王乃密諭宣猛將軍朱買臣，使為之所。", literal: "\" The prince then secretly instructed Fierce General Zhu Maichen to handle it.", idiomatic: "\" The prince secretly instructed Fierce General Zhu Maichen to handle it." },
  { zh: "及景敗，太宗已殂，豫章王棟及二弟橋、樛相扶出於密室，逢杜崱則於道，為去其鎖。", literal: "When Jing was defeated, Emperor Taizong was already dead; Prince Dong of Yuzhang and his two younger brothers Qiao and Jiu supported each other out of the secret chamber; they met Du Ya on the road, who removed their locks.", idiomatic: "When Jing fell, Emperor Taizong was already dead; Prince Dong of Yuzhang and his brothers Qiao and Jiu supported each other out of the secret chamber; Du Ya met them on the road and removed their locks." },
  { zh: "二弟曰：「今日始免橫死矣！", literal: "The two younger brothers said, \"Today at last we escape violent death!", idiomatic: "The younger brothers said, \"Today at last we escape violent death!" },
  { zh: "」棟曰：「倚伏難知，吾猶有懼！", literal: "\" Dong said, \"Fortune and misfortune are hard to know—I still have fear!", idiomatic: "\" Dong said, \"Fortune and misfortune are hard to know—I am still afraid!" },
  { zh: "」辛卯，遇朱買臣，呼之就船共飲，未竟，並沉於水。", literal: "\" On xinmao they met Zhu Maichen; he called them aboard a boat to drink together; before they finished, all were sunk in the water.", idiomatic: "\" On xinmao they met Zhu Maichen; he called them aboard to drink; before they finished, he drowned them all." },
  { zh: "僧辯遣陳霸先將兵向廣陵受郭元建等降，又遣使者往安慰之。", literal: "Sengbian sent Chen Baxian with troops toward Guangling to receive the surrender of Guo Yuanjian and others, and also sent envoys to comfort them.", idiomatic: "Sengbian sent Chen Baxian toward Guangling to accept the surrender of Guo Yuanjian and others, and sent envoys to reassure them." },
  { zh: "諸將多私使別索馬仗，會侯子鑒度江至廣陵，謂元建等曰：「我曹，梁之深仇，何顏復見其主！", literal: "Many generals privately sent separate envoys demanding horses and arms; when Hou Zijian crossed the river to Guangling, he said to Yuanjian and others, \"We are the Liang's deepest enemies—what face have we to see their lord again!", idiomatic: "Many generals privately sent envoys demanding horses and arms; when Hou Zijian crossed to Guangling, he told Yuanjian and others, \"We are the Liang's deepest enemies—what face have we to see their lord again!" },
  { zh: "不若投北，可得還鄉。", literal: "Better submit to the north and gain return to our homelands.", idiomatic: "Better submit to the north and go home." },
  { zh: "」遂皆降齊。", literal: "\" Thereupon all surrendered to Qi.", idiomatic: "\" Thereupon all surrendered to Qi." },
  { zh: "霸先至歐陽，齊行台辛術已據廣陵。", literal: "Baxian reached Ouyang; Qi's mobile headquarters Xin Shu had already taken Guangling.", idiomatic: "Baxian reached Ouyang; Qi's mobile headquarters Xin Shu had already taken Guangling." },
  { zh: "王偉與侯子鑒相失，直瀆戍主黃公喜獲之，送建康。", literal: "Wang Wei lost contact with Hou Zijian; the garrison commander of Zhidu, Huang Gongxi, captured him and sent him to Jiankang.", idiomatic: "Wang Wei lost Hou Zijian; Huang Gongxi, garrison commander of Zhidu, captured him and sent him to Jiankang." },
  { zh: "王僧辯問曰：「卿為賊相，不能死節，而求活草間邪？", literal: "Wang Sengbian asked, \"You served as the rebels' chancellor and could not die for your integrity—do you seek life among the weeds?", idiomatic: "Wang Sengbian asked, \"You were the rebels' chancellor and could not die with honor—do you seek life in the weeds?" },
  { zh: "」偉曰：「廢興，命也。", literal: "\" Wei said, \"Rise and fall are fate.", idiomatic: "\" Wei said, \"Rise and fall are fate." },
  { zh: "使漢帝早從偉言，明公豈有今日！", literal: "Had the Han emperor early followed Wei's words, would you, my lord, have today!", idiomatic: "Had the Han emperor early followed my counsel, would you, my lord, have today!" },
  { zh: "」尚書左丞虞騭嘗為偉所辱，乃唾其面。", literal: "\" Left Assistant Minister of Works Yu Chi had once been insulted by Wei and spat in his face.", idiomatic: "\" Left Assistant Minister Yu Chi, whom Wei had once insulted, spat in his face." },
  { zh: "偉曰：「君不讀書，不足與語！", literal: "Wei said, \"You do not read books—not worth speaking with!", idiomatic: "Wei said, \"You do not read—not worth speaking with!" },
  { zh: "」騭慚而退。", literal: "\" Chi withdrew in shame.", idiomatic: "\" Chi withdrew in shame." },
  { zh: "僧辯命羅州刺史徐嗣徽鎮朱方。", literal: "Sengbian ordered Luozhou Inspector Xu Sihui to garrison Zhufang.", idiomatic: "Sengbian ordered Luozhou inspector Xu Sihui to garrison Zhufang." },
  { zh: "壬辰，侯景至晉陵，得田遷餘兵，因驅掠居民，東趨吳郡。", literal: "On renchen, Hou Jing reached Jinling, took Tian Qian's remaining troops, drove and plundered the people, and pressed east toward Wu commandery.", idiomatic: "On renchen, Hou Jing reached Jinling, took Tian Qian's remaining troops, plundered the people, and pressed east toward Wu commandery." },
  { zh: "夏，四月，齊主使大都督潘樂與郭元建將兵五萬攻陽平。", literal: "In summer, the fourth month, the Qi emperor sent Grand Commander Pan Yue and Guo Yuanjian to lead fifty thousand troops against Yangping.", idiomatic: "In summer, the fourth month, the Qi emperor sent Grand Commander Pan Yue and Guo Yuanjian with fifty thousand men against Yangping." },
  { zh: "拔之。", literal: "They took it.", idiomatic: "They took it." },
  { zh: "王僧辯啟陳霸先鎮京口。", literal: "Wang Sengbian memorialized that Chen Baxian should garrison Jingkou.", idiomatic: "Wang Sengbian asked that Chen Baxian garrison Jingkou." },
  { zh: "益州刺史、太尉武陵王紀，頗有武略，在蜀十七年，南開寧州、越巂，西通資陵、吐谷渾，內修耕桑鹽鐵之政，外通商賈遠方之利，故能殖其財用，器甲殷積，有馬八千匹。", literal: "Yizhou Inspector and Grand Commandant Prince Ji of Wuling was quite skilled in military affairs; in Shu for seventeen years he opened Ningzhou and Yuexi to the south, connected to Ziling and Tuyuhun to the west, within cultivated farming, silkworms, salt, and iron, without traded with merchants for distant profit, and so amassed wealth, piled arms and armor in abundance, and had eight thousand horses.", idiomatic: "Yizhou inspector and Grand Commandant Prince Ji of Wuling was skilled in war; seventeen years in Shu he opened Ningzhou and Yuexi to the south, reached Ziling and Tuyuhun to the west, within cultivated farming, salt, and iron, without traded for distant profit, amassed wealth, stockpiled arms, and had eight thousand horses." },
  { zh: "聞侯景陷台城，湘東王將討之，謂僚佐曰：「七官文士，豈能匡濟！", literal: "Hearing that Hou Jing had taken the palace city and that the Prince of Xiangdong was about to campaign against him, he told his staff, \"The seven officials are literary men—how can they save the realm!", idiomatic: "Hearing that Hou Jing had taken the palace city and the Prince of Xiangdong was marching against him, he told his staff, \"The seven princes are literary men—how can they save the realm!" },
  { zh: "」內寢柏殿柱繞節生花，紀以為己瑞。", literal: "\" In the inner chamber of the cypress hall, knots on the pillars flowered; Ji took this as his own auspice.", idiomatic: "\" In the inner cypress hall, knots on the pillars flowered; Ji took it as his own omen." },
  { zh: "乙巳，即皇帝位，改元天正，立子圓照為皇太子，圓正為西陽王，圓滿為竟陵王，圓普為譙王，圓肅為宜都王。", literal: "On yisi, he took the imperial throne, changed the era name to Tianzheng, made son Yuanzhao crown prince, Yuanzheng Prince of Xiyang, Yuanman Prince of Jingling, Yuanpu Prince of Qiao, and Yuansu Prince of Yidu.", idiomatic: "On yisi, he took the throne, changed the era name to Tianzheng, made son Yuanzhao crown prince, Yuanzheng Prince of Xiyang, Yuanman Prince of Jingling, Yuanpu Prince of Qiao, and Yuansu Prince of Yidu." },
  { zh: "以巴西、梓潼二郡太守永豐侯手為為征西大將軍、益州刺史，封秦郡王。", literal: "He made Shouwei, Marquis of Yongfeng, Administrator of the two commanderies Baxi and Zitong, Grand General Who Conquers the West and Inspector of Yizhou, and enfeoffed him as Prince of Qin commandery.", idiomatic: "He made Shouwei, Marquis of Yongfeng, administrator of Baxi and Zitong, Grand General Who Conquers the West and inspector of Yizhou, and enfeoffed him as Prince of Qin commandery." },
  { zh: "司馬王僧略、直兵參軍徐怦固諫，不從。", literal: "Chief Administrator Wang Senglue and Direct Troops Aide Xu Zheng remonstrated firmly; he would not listen.", idiomatic: "Chief Administrator Wang Senglue and Direct Troops Aide Xu Zheng remonstrated firmly; he would not listen." },
  { zh: "僧略，僧辯之弟；", literal: "Senglue was Sengbian's younger brother.", idiomatic: "Senglue was Sengbian's younger brother." },
  { zh: "怦，勉之從子也。", literal: "Zheng was Mian's nephew.", idiomatic: "Zheng was Mian's nephew." },
  { zh: "初，台城之圍，怦勸紀速入援，紀意不欲行，內銜之。", literal: "Earlier, during the siege of the palace city, Zheng urged Ji to enter quickly in relief; Ji did not wish to go and harbored resentment within.", idiomatic: "Earlier, during the siege of the palace city, Zheng had urged Ji to march quickly in relief; Ji had not wished to go and harbored resentment." },
  { zh: "會蜀人費合告怦反，怦有與將帥書云：「事事往人口具。", literal: "It happened that the Shu man Fei He reported that Zheng was rebelling; Zheng had a letter to a commander saying, \"Every matter is to be delivered in person by mouth.", idiomatic: "A Shu man named Fei He reported that Zheng was rebelling; Zheng had written a commander, \"Every matter is to be delivered in person by mouth." },
  { zh: "」紀即以為反征，謂怦曰：「以卿舊情，當使諸子無恙。", literal: "\" Ji at once took this as evidence of rebellion and told Zheng, \"Out of our old bond, I shall see that your sons come to no harm.", idiomatic: "\" Ji took this as proof of rebellion and told Zheng, \"For our old bond, I shall see that your sons come to no harm." },
  { zh: "」對曰：「生兒悉如殿下，留之何益！", literal: "\" He answered, \"If sons are all like Your Highness, what good is keeping them!", idiomatic: "\" He answered, \"If sons are all like Your Highness, what good is keeping them!" },
  { zh: "」紀乃盡誅之，梟首於市，亦殺王僧略。", literal: "\" Ji then executed them all, displayed their heads in the market, and also killed Wang Senglue.", idiomatic: "\" Ji executed them all, displayed their heads in the market, and killed Wang Senglue as well." },
  { zh: "永豐侯手為歎曰：「王事不成矣！", literal: "Marquis Shouwei of Yongfeng sighed and said, \"The royal enterprise is finished!", idiomatic: "Marquis Shouwei of Yongfeng sighed: \"The royal enterprise is finished!" },
  { zh: "善人，國之基也，今先殺之，不亡何待！", literal: "Good men are the foundation of a state—now killing them first, how can it not perish!", idiomatic: "Good men are the foundation of a state—kill them first, and what is left but ruin!" },
  { zh: "紀征宜豐侯咨議參軍劉璠為中書侍郎，使者八反，乃至。", literal: "Ji summoned Liu Fan, Consultant of the Marquis of Yifeng, as Palace Secretary; envoys went back and forth eight times before he came.", idiomatic: "Ji summoned Liu Fan, consultant of the Marquis of Yifeng, as Palace Secretary; envoys went back and forth eight times before he came." },
  { zh: "紀令劉孝勝深布腹心，璠苦求還。", literal: "Ji had Liu Xiaosheng lay bare his inmost heart; Fan urgently asked to return.", idiomatic: "Ji had Liu Xiaosheng speak his inmost mind; Fan urgently asked to return." },
  { zh: "中記室韋登私謂璠曰：「殿下忍而畜憾，足下不留，將致大禍，孰若共構大夏，使身名俱美哉！", literal: "Central Recorder Wei Deng privately told Fan, \"His Highness is forbearing yet hoards grievance; if you do not stay, great disaster will come—why not together build a great house and make body and name both fair!", idiomatic: "Central Recorder Wei Deng told Fan privately, \"His Highness is patient but hoards grievance; if you do not stay, disaster follows—why not build a great enterprise together and win honor for us both?" },
  { zh: "」璠正色曰：「卿欲緩頰於我邪？", literal: "\" Fan said sternly, \"Do you wish to plead for me?", idiomatic: "\" Fan said sternly, \"Do you wish to plead for me?" },
  { zh: "我與府侯分義已定，豈以夷險易其心乎！", literal: "My bond with the marquis is fixed in duty—how could I change my heart for ease or peril!", idiomatic: "My bond with the marquis is fixed—how could ease or peril change my heart!" },
  { zh: "殿下方布大義於天下，終不逞志於一夫。", literal: "His Highness is now spreading great righteousness through the realm—he will never vent his will on one man.", idiomatic: "His Highness spreads righteousness through the realm—he will never vent his will on one man." },
  { zh: "」紀知必不為己用，乃厚禮遣之。", literal: "\" Ji knew he would never serve him and so sent him away with rich gifts.", idiomatic: "\" Ji knew Fan would never serve him and sent him away with rich gifts." },
  { zh: "以宜豐侯循為益州刺史，封隨郡王，以璠為循府長史、蜀郡太守。", literal: "He made the Marquis of Yifeng, Xun, Inspector of Yizhou and enfeoffed him as Prince of Sui commandery, and made Fan Xun's chief secretary and Administrator of Shu commandery.", idiomatic: "He made the Marquis of Yifeng, Xun, inspector of Yizhou and Prince of Sui commandery, and made Fan Xun's chief secretary and administrator of Shu commandery." },
  { zh: "謝答仁討劉神茂還，至富陽，聞侯景敗走，帥萬人欲北出候之，趙伯超據錢塘拒之。", literal: "Xie Daren, returning from campaigning against Liu Shenma, reached Fuyang; hearing that Hou Jing had been defeated and was fleeing, he led ten thousand men wishing to go north to meet him; Zhao Bochao held Qiantang and barred him.", idiomatic: "Xie Daren, returning from the campaign against Liu Shenma, reached Fuyang; hearing Hou Jing was fleeing, he led ten thousand men north to meet him; Zhao Bochao held Qiantang and barred him." },
  { zh: "侯景進至嘉興，聞伯超叛之，乃退據吳。", literal: "Hou Jing advanced to Jiaxing; hearing that Bochao had rebelled against him, he withdrew and held Wu.", idiomatic: "Hou Jing advanced to Jiaxing; hearing Bochao had turned on him, he withdrew to Wu." },
  { zh: "己酉，侯瑱追及景於松江，景猶有船二百艘，眾數千人，瑱進擊，敗之，擒彭雋、田遷、房世貴、蔡壽樂、王伯丑。", literal: "On jiyou, Hou Tian overtook Jing at Songjiang; Jing still had two hundred ships and several thousand men; Tian pressed the attack, defeated him, and captured Peng Juan, Tian Qian, Fang Shigui, Cai Shoule, and Wang Bochou.", idiomatic: "On jiyou, Hou Tian overtook Jing at Songjiang; Jing still had two hundred ships and several thousand men; Tian attacked, routed him, and captured Peng Juan, Tian Qian, Fang Shigui, Cai Shoule, and Wang Bochou." },
  { zh: "瑱生剖雋腹，抽其腸。", literal: "Tian cut open Juan's belly alive and drew out his intestines.", idiomatic: "Tian cut Juan's belly open alive and drew out his intestines." },
  { zh: "雋猶不死，手自收之，乃斬之。", literal: "Juan still did not die; with his own hands he gathered them in, and only then was he beheaded.", idiomatic: "Juan still lived; with his own hands he gathered them in, and only then was he beheaded." },
  { zh: "景與腹心數十人單舸走，推墮二子於水，將入海，瑱遣副將焦僧度追之。", literal: "Jing with several dozen trusted men fled in a single boat, pushed his two sons into the water, and was about to go to sea; Tian sent Deputy General Jiao Songdu in pursuit.", idiomatic: "Jing fled in a single boat with several dozen trusted men, pushed his two sons into the water, and headed for the sea; Tian sent Deputy General Jiao Songdu in pursuit." },
  { zh: "景納羊侃之女為小妻，以其兄昆為庫直都督，待之甚厚。", literal: "Jing had taken Yang Kan's daughter as a minor wife and made her elder brother Kun Director of the Palace Armory, treating him very generously.", idiomatic: "Jing had taken Yang Kan's daughter as a concubine and made her brother Kun Director of the Palace Armory, treating him generously." },
  { zh: "昆隨景東走，與景所親王元禮、謝葳蕤密圖之。", literal: "Kun followed Jing east and with Jing's intimate Wang Yuanli and Xie Weirui secretly plotted against him.", idiomatic: "Kun followed Jing east and with Jing's intimates Wang Yuanli and Xie Weirui secretly plotted against him." },
  { zh: "葳蕤，答仁之弟也。", literal: "Weirui was Daren's younger brother.", idiomatic: "Weirui was Daren's younger brother." },
  { zh: "景下海，欲向蒙山，己卯，景晝寢；", literal: "Jing went down to the sea intending to head for Meng Mountain; on jimao, Jing napped by day.", idiomatic: "Jing put to sea intending for Meng Mountain; on jimao he napped by day." },
  { zh: "昆語海師：「此中何處有蒙山，汝但聽我處分。", literal: "Kun told the sea pilot, \"Where is there Meng Mountain here—you need only obey my orders.", idiomatic: "Kun told the pilot, \"Where is Meng Mountain here—you need only obey me." },
  { zh: "」遂直向京口。", literal: "\" Thereupon they headed straight for Jingkou.", idiomatic: "\" Thereupon they headed straight for Jingkou." },
  { zh: "至胡豆洲，景覺，大驚；", literal: "When they reached Houdou Isle, Jing awoke, greatly alarmed;", idiomatic: "When they reached Houdou Isle, Jing awoke in alarm;" },
  { zh: "問岸上人，云「郭元建猶在廣陵」，景大喜，將依之。", literal: "he asked people on the shore, who said, \"Guo Yuanjian is still at Guangling\"; Jing was overjoyed and meant to rely on him.", idiomatic: "he asked people on the shore, who said, \"Guo Yuanjian is still at Guangling\"; Jing was overjoyed and meant to go to him." },
  { zh: "昆拔刀，叱海師向京口，因謂景曰：「吾等為王效力多矣，今至於此，終無所成，欲就乞頭以取富貴。", literal: "Kun drew his blade, shouted at the helmsman to steer for Jingkou, and said to Jing, \"We have served Your Majesty long and hard; now it has come to this with nothing achieved—we mean to beg your head for wealth and rank.", idiomatic: "Kun drew his blade, shouted at the helmsman to steer for Jingkou, and told Jing, \"We have served you long and hard; now it has come to nothing—we mean to take your head for our reward.\"" },
  { zh: "」景未及答，白刃交下。", literal: "\" Before Jing could answer, white blades struck from every side.", idiomatic: "\" Before Jing could answer, blades flashed down on every side." },
  { zh: "景欲投水，昆以刀斫之。", literal: "Jing tried to throw himself into the water; Kun hacked him with a blade.", idiomatic: "Jing tried to throw himself into the water; Kun hacked at him with a blade." },
  { zh: "景走入船中，以佩刀抉船底，昆以槊刺殺之。", literal: "Jing ran into the boat and gouged the bottom with his belt dagger; Kun speared and killed him.", idiomatic: "Jing ran into the boat and gouged the hull with his belt dagger; Kun ran him through with a spear and killed him." },
  { zh: "尚書右僕射索超世在別船，葳蕤以景命召而執之。", literal: "Right Vice Director of the Secretariat Suo Chaoshi was on another vessel; Weirui summoned and seized him in Jing's name.", idiomatic: "Right vice director of the secretariat Suo Chaoshi was on another vessel; Weirui summoned and seized him in Jing's name." },
  { zh: "南徐州刺史徐嗣徽斬超世，以鹽內景腹中，送其屍於建康。", literal: "Southern Xuzhou Inspector Xu Siwei beheaded Chaoshi, packed Jing's belly with salt, and sent the corpse to Jiankang.", idiomatic: "Southern Xuzhou inspector Xu Siwei beheaded Chaoshi, packed Jing's belly with salt, and sent the corpse to Jiankang." },
  { zh: "僧辯傳首江陵，截其手，使謝葳蕤送於齊；", literal: "Senbian sent the head to Jiangling and cut off the hands, had Xie Weirui deliver them to Qi;", idiomatic: "Senbian sent the head to Jiangling and cut off the hands, and had Xie Weirui deliver them to Qi;" },
  { zh: "暴景屍於市，士民爭取食之，並骨皆盡；", literal: "Jing's corpse was exposed in the market; gentlemen and commoners scrambled to eat it until even the bones were gone;", idiomatic: "Jing's corpse was exposed in the market; townspeople scrambled to eat it until even the bones were gone;" },
  { zh: "溧陽公主亦預食焉。", literal: "the Princess of Liyang also took part in the eating.", idiomatic: "even the Princess of Liyang took part." },
  { zh: "初，景之五子在北齊，世宗剝其長子面而烹之，幼者皆下蠶室。", literal: "Earlier, Jing's five sons were in Northern Qi; Shizong flayed the eldest's face and boiled him, and the younger ones were all sent to the silkworm house.", idiomatic: "Earlier, Jing's five sons were in Northern Qi; Emperor Wenxuan flayed the eldest's face and boiled him, and the younger ones were all castrated." },
  { zh: "齊顯祖即位，夢獼猴坐其御床，乃盡烹之。", literal: "When Qi Emperor Xianzu took the throne, he dreamed a macaque sat on his imperial couch and then had them all boiled.", idiomatic: "When Emperor Wenxuan of Qi took the throne, he dreamed a macaque sat on his imperial couch and had them all boiled." },
  { zh: "趙伯超、謝答仁皆降於侯瑱，瑱並田遷等送建康。", literal: "Zhao Bochao and Xie Daren both surrendered to Hou Chen; Chen sent them with Tian Qian and others to Jiankang.", idiomatic: "Zhao Bochao and Xie Daren both surrendered to Hou Chen; Chen sent them with Tian Qian and others to Jiankang." },
  { zh: "王僧辯斬房世貴於市，送王偉、呂季略、周石珍、嚴但、趙伯超、伏知命於江陵。", literal: "Wang Senbian executed Fang Shigui in the market and sent Wang Wei, Lü Jilüe, Zhou Shizhen, Yan Dan, Zhao Bochao, and Fu Zhiming to Jiangling.", idiomatic: "Wang Senbian executed Fang Shigui in the market and sent Wang Wei, Lü Jilüe, Zhou Shizhen, Yan Dan, Zhao Bochao, and Fu Zhiming to Jiangling." },
  { zh: "丁巳，湘東王下令解嚴。", literal: "On dingsi, the Prince of Xiangdong ordered the lifting of martial law.", idiomatic: "On dingsi, Prince Xiao Yi of Xiangdong ordered the lifting of martial law." },
  { zh: "乙丑，葬簡文帝於莊陵，廟號太宗。", literal: "On yichou, Emperor Jianwen was buried at Zhuangling; his temple name was Taizong.", idiomatic: "On yichou, Emperor Jianwen was buried at Zhuangling; his temple name was Taizong." },
  { zh: "侯景之敗也，以傳國璽自隨，使其侍中兼平原太守趙思賢掌之，曰：「若我死，宜沉於江，勿令吳兒復得之。", literal: "When Hou Jing was defeated, he carried the imperial seal with him and had his attendant-in-ordinary and concurrent Administrator of Pingyuan Zhao Sixian keep it, saying, \"If I die, sink it in the river—do not let the Wu men get it again.", idiomatic: "When Hou Jing was defeated, he carried the imperial seal with him and had attendant-in-ordinary and concurrent administrator of Pingyuan Zhao Sixian keep it, saying, \"If I die, sink it in the river—do not let the southerners have it again.\"" },
  { zh: "」思賢自京口濟江，遇盜，從者棄之草間，至廣陵，以告郭元建。", literal: "\" Sixian crossed the river from Jingkou, met bandits, and his attendants abandoned it in the grass; reaching Guangling, he told Guo Yuanjian.", idiomatic: "\" Sixian crossed the river from Jingkou, met bandits, and his attendants abandoned it in the grass; reaching Guangling, he told Guo Yuanjian." },
  { zh: "元建取之，以與辛術，壬申，術送之至鄴。", literal: "Yuanjian took it and gave it to Xin Shu; on renshen, Shu sent it to Ye.", idiomatic: "Yuanjian took it and gave it to Xin Shu; on renshen, Shu sent it to Ye." },
  { zh: "甲申，齊以吏部尚書楊愔為右僕射，以太原公主妻之。", literal: "On jiashen, Qi made Minister of Personnel Yang Yin Right Vice Director and gave him the Princess of Taiyuan in marriage.", idiomatic: "On jiashen, Qi made minister of personnel Yang Yin right vice director and gave him the Princess of Taiyuan in marriage." },
  { zh: "公主即魏孝靜帝之後也。", literal: "The princess was a daughter of Wei Emperor Xiaojing.", idiomatic: "The princess was a daughter of Wei Emperor Xiaojing." },
  { zh: "楊乾運至劍北，魏達奚武逆擊之，大破乾運於白馬，陳其俘馘於南鄭城下，且遣人辱宜豐侯循。", literal: "Yang Qianyun reached north of Jian; Wei's Daqixin Wu met and struck him, routing Qianyun at Baima, displayed captives and heads below Nanzheng, and also sent men to insult Marquis Xun of Yifeng.", idiomatic: "Yang Qianyun reached north of Jian; Western Wei's Daqixin Wu met and struck him, routing Qianyun at Baima, displayed captives and heads below Nanzheng, and sent men to insult Marquis Xiao Xun of Yifeng." },
  { zh: "循怒，出兵與戰，都督楊紹伏兵擊之，殺傷殆盡。", literal: "Xun was angry, marched out to fight, and Commander Yang Shao ambushed them, killing and wounding nearly all.", idiomatic: "Xun was angry, marched out to fight, and commander Yang Shao ambushed them, killing and wounding nearly all." },
  { zh: "劉愔還至白馬西，為武所獲，送長安。", literal: "Liu Yin, returning west of Baima, was captured by Wu and sent to Chang'an.", idiomatic: "Liu Fan, returning west of Baima, was captured by Wu and sent to Chang'an." },
  { zh: "太師泰素聞其名，待之如舊交。", literal: "Grand Preceptor Tai had long heard his name and treated him as an old friend.", idiomatic: "Grand preceptor Yuwen Tai had long heard his name and treated him as an old friend." },
  { zh: "時南鄭久不下，武請屠之，泰將許之。", literal: "Nanzheng had long not fallen; Wu asked to slaughter it, and Tai was about to consent.", idiomatic: "Nanzheng had long not fallen; Wu asked to slaughter it, and Tai was about to consent." },
  { zh: "璠請之於朝，泰怒，不許；", literal: "Fan pleaded at court; Tai was angry and refused;", idiomatic: "Fan pleaded at court; Tai was angry and refused;" },
  { zh: "璠泣請不已，泰曰：「事人當如是。", literal: "Fan wept and pleaded without cease; Tai said, \"Serving a lord should be like this.", idiomatic: "Fan wept and pleaded without cease; Tai said, \"This is how one should serve a lord.\"" },
  { zh: "」乃從其請。", literal: "\" He then granted the request.", idiomatic: "\" He then granted the request." },
  { zh: "五月，庚午，司空南平王恪等復勸進，湘東王猶不受，遣侍中豐城侯泰等謁山陵，修復廟社。", literal: "In the fifth month, on gengwu, Minister of Works Prince Ke of Nanping and others again urged accession; the Prince of Xiangdong still refused and sent Attendant-in-Ordinary Marquis Tai of Fengcheng and others to visit the imperial tombs and restore the ancestral temples and altars.", idiomatic: "In the fifth month, on gengwu, minister of works Prince Xiao Ke of Nanping and others again urged accession; Prince Xiao Yi still refused and sent attendant-in-ordinary Marquis Tai of Fengcheng and others to visit the imperial tombs and restore the ancestral temples and altars." },
  { zh: "戊寅，侯景首至江陵，梟之於市三日，煮而漆之，以付武庫。", literal: "On wuyin, Jing's head reached Jiangling; it was exposed in the market three days, then boiled, lacquered, and placed in the armory.", idiomatic: "On wuyin, Jing's head reached Jiangling; it was exposed in the market three days, then boiled, lacquered, and placed in the armory." },
  { zh: "庚辰，以南平王恪為揚州刺史。", literal: "On gengchen, Prince Ke of Nanping was made Inspector of Yangzhou.", idiomatic: "On gengchen, Prince Xiao Ke of Nanping was made inspector of Yangzhou." },
  { zh: "甲申，以王僧辯為司徒、鎮衛將軍，封長寧公。", literal: "On jiashen, Wang Senbian was made Minister of Education and General Who Guards the Realm, enfeoffed as Duke of Changning.", idiomatic: "On jiashen, Wang Senbian was made minister of education and general who guards the realm, enfeoffed as Duke of Changning." },
  { zh: "陳霸先為征虜將軍、開府儀同三司，封長城縣侯。", literal: "Chen Baxian was made General Who Punishes the Barbarians, equal in honor to the three dukes with an open office, and enfeoffed as Marquis of Changcheng.", idiomatic: "Chen Baxian was made general who punishes the barbarians, equal in honor to the three dukes with an open office, and enfeoffed as Marquis of Changcheng." },
  { zh: "乙酉，誅侯景所署尚書僕射王偉、左民尚書呂季略、少府周石珍、舍人嚴但於市。", literal: "On yiyou, Jing's appointees—Vice Director of the Secretariat Wang Wei, Director of the Left Bureau Lü Jilüe, Chamberlain for the Palace Treasury Zhou Shizhen, and Gentleman Attendant Yan Dan—were executed in the market.", idiomatic: "On yiyou, Jing's appointees—vice director of the secretariat Wang Wei, director of the left bureau Lü Jilüe, chamberlain for the palace treasury Zhou Shizhen, and gentleman attendant Yan Dan—were executed in the market." },
  { zh: "趙伯超、伏知命餓死於獄。", literal: "Zhao Bochao and Fu Zhiming starved to death in prison.", idiomatic: "Zhao Bochao and Fu Zhiming starved to death in prison." },
  { zh: "以謝答仁不失禮於太宗，特宥之。", literal: "Because Xie Daren had not failed in courtesy toward Taizong, he was specially spared.", idiomatic: "Because Xie Daren had not failed in courtesy toward Taizong, he was specially spared." },
  { zh: "王偉於獄中上五百言詩，湘東王愛其才，欲宥之。", literal: "Wang Wei submitted a five-hundred-word poem from prison; the Prince of Xiangdong admired his talent and wished to spare him.", idiomatic: "Wang Wei submitted a five-hundred-word poem from prison; Prince Xiao Yi admired his talent and wished to spare him." },
  { zh: "有嫉之者，言於王曰：「前日偉作檄文甚佳。", literal: "One who envied him said to the prince, \"The other day Wei wrote an excellent proclamation.", idiomatic: "A jealous courtier said to the prince, \"The other day Wei wrote an excellent proclamation.\"" },
  { zh: "」王求而視之，檄曰：「項羽重瞳，尚有烏江之敗；", literal: "\" The prince asked to see it; the text read, \"Xiang Yu had double pupils, yet still met defeat at the Wu River;", idiomatic: "\" The prince asked to see it; the text read, \"Xiang Yu had double pupils, yet still met defeat at the Wu River;\"" },
  { zh: "湘東一目，寧為赤縣所歸！", literal: "the Prince of Xiangdong has but one eye—how should the empire submit to him!", idiomatic: "the Prince of Xiangdong has but one eye—how should the empire submit to him!\"" },
  { zh: "」王大怒，釘其舌於柱，剜腹、臠肉而殺之。", literal: "\" The prince was furious, nailed his tongue to a post, disemboweled him, carved his flesh, and killed him.", idiomatic: "\" The prince was furious, nailed his tongue to a post, disemboweled him, carved his flesh, and killed him." },
  { zh: "丙戌，齊合州刺史斛斯昭攻歷陽，拔之。", literal: "On bingxu, Qi's Hezhou Inspector Husizhao attacked Liyang and took it.", idiomatic: "On bingxu, Qi's Hezhou inspector Husizhao attacked Liyang and took it." },
  { zh: "丁亥，下令，以「王偉等既死，自餘衣冠舊貴，被逼偷生，猛士勳豪，和光苟免者，皆不問。", literal: "On dinghai, an order was issued: \"Now that Wang Wei and the rest are dead, all other gentry and old nobles who were forced to live in hiding, and bold warriors and meritorious lords who blended in to escape—all will go unpunished.", idiomatic: "On dinghai, an order was issued: \"Now that Wang Wei and the rest are dead, all other gentry and old nobles who were forced to live in hiding, and bold warriors and meritorious lords who blended in to escape—all will go unpunished.\"" },
  { zh: "扶風民魯悉達，糾合鄉人以保新蔡，力田蓄谷。", literal: "Lu Sida of Fufeng gathered villagers to hold Xincai, farmed diligently, and stored grain.", idiomatic: "Lu Sida of Fufeng gathered villagers to hold Xincai, farmed diligently, and stored grain." },
  { zh: "時江東饑亂，餓死者什八九，遺民攜老幼歸之。", literal: "The Jiangdong region was starving and in chaos; eight or nine in ten died of hunger, and survivors brought old and young to join him.", idiomatic: "The Jiangdong region was starving and in chaos; eight or nine in ten died of hunger, and survivors brought old and young to join him." },
  { zh: "悉達分給糧廩，全濟甚眾，招集晉熙等五郡，盡有其地。", literal: "Sida distributed grain from his stores and saved a great many; he gathered five commanderies including Jinxi and held all their territory.", idiomatic: "Sida distributed grain from his stores and saved a great many; he gathered five commanderies including Jinxi and held all their territory." },
  { zh: "使其弟廣達將兵從王僧辯討侯景，景平，以悉達為北江州刺史。", literal: "He sent his younger brother Guangda with troops to follow Wang Senbian against Hou Jing; when Jing was pacified, Sida was made Inspector of Northern Jiangzhou.", idiomatic: "He sent his younger brother Guangda with troops to follow Wang Senbian against Hou Jing; when Jing was pacified, Sida was made inspector of Northern Jiangzhou." },
  { zh: "齊主使其散騎常侍曹文皎等來聘，湘東王使散騎常侍柳暉等報之，且告平侯景；", literal: "The Qi ruler sent Supernumerary Cavalier Attendant Cao Wenjiao and others on a friendly mission; the Prince of Xiangdong sent Supernumerary Cavalier Attendant Liu Hui and others in reply, also announcing the pacification of Hou Jing;", idiomatic: "The Qi ruler sent supernumerary cavalier attendant Cao Wenjiao and others on a friendly mission; Prince Xiao Yi sent supernumerary cavalier attendant Liu Hui and others in reply, also announcing the pacification of Hou Jing;" },
  { zh: "亦遣舍人魏彥告於魏。", literal: "he also sent Gentleman Attendant Wei Yan to inform Wei.", idiomatic: "he also sent gentleman attendant Wei Yan to inform Western Wei." },
  { zh: "齊主使潘樂、郭元建將兵圍秦郡，行台尚書辛術諫曰：「朝廷與湘東王信使不絕。", literal: "The Qi ruler sent Pan Yue and Guo Yuanjian with troops to besiege Qin Commandery; Mobile Secretariat Director Xin Shu remonstrated, \"Court and the Prince of Xiangdong have messengers going back and forth without cease.", idiomatic: "The Qi ruler sent Pan Yue and Guo Yuanjian with troops to besiege Qin Commandery; mobile secretariat director Xin Shu remonstrated, \"Court and Prince Xiao Yi of Xiangdong have messengers going back and forth without cease.\"" },
  { zh: "陽平，侯景之土，取之可也；", literal: "Yangping was Hou Jing's territory—taking it is acceptable;", idiomatic: "Yangping was Hou Jing's territory—taking it is acceptable;" },
  { zh: "今王僧辯已遣嚴超達守秦郡，於義何得復爭之！", literal: "but Wang Senbian has already sent Yan Chaoda to hold Qin Commandery—by what right should we fight over it again!", idiomatic: "but Wang Senbian has already sent Yan Chaoda to hold Qin Commandery—by what right should we fight over it again!\"" },
  { zh: "且水潦方降，不如班師。", literal: "Moreover floods are coming down—better to withdraw the army.", idiomatic: "Moreover floods are coming down—better to withdraw the army.\"" },
  { zh: "」弗從。", literal: "\" He was not obeyed.", idiomatic: "\" He was not obeyed." },
  { zh: "陳霸先命別將徐度引兵助秦郡固守。", literal: "Chen Baxian ordered detached general Xu Du to lead troops to help Qin Commandery hold firm.", idiomatic: "Chen Baxian ordered detached general Xu Du to lead troops to help Qin Commandery hold firm." },
  { zh: "齊眾七萬，攻之甚急。", literal: "The Qi host numbered seventy thousand and pressed the attack fiercely.", idiomatic: "The Qi host numbered seventy thousand and pressed the attack fiercely." },
  { zh: "王僧辯使左衛將軍杜崱救之，霸先亦自歐陽來會；", literal: "Wang Senbian sent Left Guard General Du Ya to rescue it, and Baxian also came from Ouyang to join;", idiomatic: "Wang Senbian sent left guard general Du Ya to rescue it, and Baxian also came from Ouyang to join;" },
  { zh: "與元建大戰於土林，大破之，斬首萬餘級，生擒千餘人，元建收餘眾北遁；", literal: "they fought Yuanjian in great battle at Tulin, routed him utterly, took more than ten thousand heads, captured more than a thousand alive, and Yuanjian gathered the remnant and fled north;", idiomatic: "they fought Yuanjian in great battle at Tulin, routed him utterly, took more than ten thousand heads, captured more than a thousand alive, and Yuanjian gathered the remnant and fled north;" },
  { zh: "猶以通好，不窮追也。", literal: "yet because friendly relations continued, they did not pursue to the end.", idiomatic: "yet because friendly relations continued, they did not pursue to the end." },
  { zh: "辛術遷吏部尚書。", literal: "Xin Shu was transferred to Minister of Personnel.", idiomatic: "Xin Shu was transferred to minister of personnel." },
  { zh: "自魏遷鄴以來，大選之職，知名者數人，互有得失：齊世宗少年高朗，所弊者疏；", literal: "Since Wei moved the capital to Ye, several famous men had held the great selection office, each with strengths and flaws: Qi's Shizong was young, lofty, and clear, but his fault was laxity;", idiomatic: "Since Wei moved the capital to Ye, several famous men had held the great selection office, each with strengths and flaws: Qi's Shizong was young, lofty, and clear, but his fault was laxity;" },
  { zh: "袁叔德沈密謹厚，所傷者細；", literal: "Yuan Shude was deep, careful, and earnest, but harmed by minuteness;", idiomatic: "Yuan Shude was deep, careful, and earnest, but harmed by minuteness;" },
  { zh: "楊愔風流辯給，取士失於浮華。", literal: "Yang Yin was elegant and eloquent, but erred toward flash in choosing men.", idiomatic: "Yang Yin was elegant and eloquent, but erred toward flash in choosing men." },
  { zh: "唯術性尚貞明，取士必以才器，循名責實，新舊參舉，管庫必擢，門閥不遺，考之前後，最為折衷。", literal: "Only Shu was upright and clear in nature, always choosing men by talent and capacity, matching names to reality, mixing old and new appointments, promoting even storehouse clerks and not overlooking great houses—in all, the most balanced of them.", idiomatic: "Only Shu was upright and clear in nature, always choosing men by talent and capacity, matching names to reality, mixing old and new appointments, promoting even storehouse clerks and not overlooking great houses—in all, the most balanced of them." },
  { zh: "魏達奚武遣尚書左丞柳帶韋入南鄭，說宜豐侯循曰：「足下所固者險，所恃者援，所保者民。", literal: "Wei's Daqixin Wu sent Left Assistant Director of the Secretariat Liu Daiwei into Nanzheng to persuade Marquis Xun of Yifeng: \"What you rely on is terrain, what you count on is aid, what you guard is the people.", idiomatic: "Western Wei's Daqixin Wu sent left assistant director of the secretariat Liu Daiwei into Nanzheng to persuade Marquis Xiao Xun of Yifeng: \"What you rely on is terrain, what you count on is aid, what you guard is the people.\"" },
  { zh: "今王旅深入，所憑之險不足固也；", literal: "Now the royal army has penetrated deep; the passes you trust are not secure enough;", idiomatic: "Now the royal army has penetrated deep; the passes you trust are not secure enough;" },
  { zh: "白馬破走，酋豪不進，所望之援不可恃也；", literal: "Baima was broken and fled, chieftains would not advance—the aid you hope for cannot be relied on;", idiomatic: "Baima was broken and fled, chieftains would not advance—the aid you hope for cannot be relied on;" },
  { zh: "長圍四合，所部之民不可保也。", literal: "long encirclement closes on four sides—the people under you cannot be protected.", idiomatic: "long encirclement closes on four sides—the people under you cannot be protected.\"" },
  { zh: "且足下本朝喪亂，社稷無主，欲誰為為忠乎！", literal: "Moreover your own court is in chaos and the altars have no lord—to whom would you be loyal!", idiomatic: "Moreover your own court is in chaos and the altars have no lord—to whom would you be loyal!\"" },
  { zh: "豈若轉禍為福，使慶流子孫邪！", literal: "Would it not be better to turn disaster into blessing and let fortune flow to your descendants?", idiomatic: "Would it not be better to turn disaster into blessing and let fortune flow to your descendants?\"" },
  { zh: "」循乃請降。", literal: "\" Xun then asked to surrender.", idiomatic: "\" Xun then asked to surrender." },
  { zh: "帶韋，慶之子也。", literal: "Daiwei was Qing's son.", idiomatic: "Daiwei was Liu Qing's son." },
  { zh: "開府儀同三司賀蘭德願聞城中食盡，請攻之，大都督赫連達曰：「不戰而獲城，策之上者，豈可利其子女，貪其貨財，而不愛民命乎！", literal: "Equal in Honor to the Three Dukes Helan Deyuan, hearing food in the city was exhausted, asked to attack; Grand Commander Helian Da said, \"Taking a city without battle is the highest strategy—how can one covet their women and children, grasp their goods, and not cherish the people's lives!", idiomatic: "Helan Deyuan, equal in honor to the three dukes, hearing food in the city was exhausted, asked to attack; grand commander Helian Da said, \"Taking a city without battle is the highest strategy—how can one covet their women and children, grasp their goods, and not cherish the people's lives!\"" },
  { zh: "且觀其士馬猶強，城池尚固，攻之縱克，必彼此俱傷；", literal: "Moreover their soldiers and horses are still strong and the walls still firm—even if attack succeeds, both sides must be wounded;", idiomatic: "Moreover their soldiers and horses are still strong and the walls still firm—even if attack succeeds, both sides must be wounded;" },
  { zh: "如困獸猶鬥，則成敗未可知也。", literal: "if a cornered beast still fights, victory and defeat cannot be known.", idiomatic: "if a cornered beast still fights, victory and defeat cannot be known.\"" },
  { zh: "」武曰：「公言是也。", literal: "\" Wu said, \"Your words are right.", idiomatic: "\" Wu said, \"Your words are right.\"" },
  { zh: "」乃受循降，獲男女二萬口而還，於是劍北皆入於魏。", literal: "\" He then accepted Xun's surrender, took twenty thousand men and women, and returned; thereupon all north of Jian passed to Wei.", idiomatic: "\" He then accepted Xun's surrender, took twenty thousand men and women, and returned; thereupon all north of Jian passed to Western Wei." },
  { zh: "六月，丁未，齊主還鄴；", literal: "In the sixth month, on dingwei, the Qi ruler returned to Ye;", idiomatic: "In the sixth month, on dingwei, the Qi ruler returned to Ye;" },
  { zh: "乙卯，復如晉陽。", literal: "on yimao, he went again to Jinyang.", idiomatic: "on yimao, he went again to Jinyang." },
  { zh: "庚寅，立安南侯方矩為王太子。", literal: "On gengyin, Marquis Fangju of Annan was installed as crown prince.", idiomatic: "On gengyin, Marquis Fangju of Annan was installed as crown prince." },
  { zh: "齊遣散騎常侍謝季卿來賀平侯景。", literal: "Qi sent Supernumerary Cavalier Attendant Xie Jiqing to congratulate the pacification of Hou Jing.", idiomatic: "Qi sent supernumerary cavalier attendant Xie Jiqing to congratulate the pacification of Hou Jing." },
  { zh: "衡州刺史王懷明作亂，廣州刺史蕭勃討平之。", literal: "Hengzhou Inspector Wang Huaiming rebelled; Guangzhou Inspector Xiao Bo suppressed and pacified him.", idiomatic: "Hengzhou inspector Wang Huaiming rebelled; Guangzhou inspector Xiao Bo suppressed and pacified him." },
  { zh: "齊政煩賦重，江北之民不樂屬齊，其豪傑數請兵於王僧辯，僧辯以與齊通好，皆不許。", literal: "Qi's government was burdensome and taxes heavy; people north of the Yangtze were unhappy under Qi rule, and local heroes repeatedly asked Wang Senbian for troops—Senbian, keeping friendly relations with Qi, refused all.", idiomatic: "Qi's government was burdensome and taxes heavy; people north of the Yangtze were unhappy under Qi rule, and local heroes repeatedly asked Wang Senbian for troops—Senbian, keeping friendly relations with Qi, refused all." },
  { zh: "秋，七月，廣陵僑人朱盛等潛聚黨數千人，謀襲殺齊刺史溫仲邕，遣使求援於陳霸先，雲已克其外城。", literal: "In autumn, the seventh month, Zhu Sheng and other sojourners at Guangling secretly gathered several thousand partisans, plotted to surprise and kill Qi's inspector Wen Zhongyong, and sent envoys to Chen Baxian for aid, claiming the outer city was already taken.", idiomatic: "In autumn, the seventh month, Zhu Sheng and other sojourners at Guangling secretly gathered several thousand partisans, plotted to surprise and kill Qi's inspector Wen Zhongyong, and sent envoys to Chen Baxian for aid, claiming the outer city was already taken." },
  { zh: "霸先使告僧辯，僧辯曰：「人之情偽，未易可測，若審克外城，亟須應援，如其不爾，無煩進軍。", literal: "Baxian sent word to Senbian; Senbian said, \"Human truth and falsehood are hard to gauge—if the outer city is truly taken, aid must come at once; if not, there is no need to march.", idiomatic: "Baxian sent word to Senbian; Senbian said, \"Human truth and falsehood are hard to gauge—if the outer city is truly taken, aid must come at once; if not, there is no need to march.\"" },
  { zh: "」使未報，霸先已濟江，僧辯乃命武州刺史杜崱等助之。", literal: "\" Before the envoy returned, Baxian had already crossed the river; Senbian then ordered Wuzhou Inspector Du Ya and others to assist.", idiomatic: "\" Before the envoy returned, Baxian had already crossed the river; Senbian then ordered Wuzhou inspector Du Ya and others to assist." },
  { zh: "會盛等謀洩，霸先因進軍圍廣陵。", literal: "Just then Sheng and the rest's plot leaked; Baxian therefore advanced and besieged Guangling.", idiomatic: "Just then Sheng and the rest's plot leaked; Baxian therefore advanced and besieged Guangling." },
  { zh: "八月，魏安康人黃眾寶反，攻魏興，執太守柳檜，進圍東梁州。", literal: "In the eighth month, Huang Zhongbao of Wei'an rebelled, attacked Weixing, seized Administrator Liu Gui, and advanced to besiege Eastern Liangzhou.", idiomatic: "In the eighth month, Huang Zhongbao of Wei'an rebelled, attacked Weixing, seized administrator Liu Gui, and advanced to besiege Eastern Liangzhou." },
  { zh: "令檜誘說城中，檜不從而死。", literal: "He ordered Gui to persuade the city to surrender; Gui refused and died.", idiomatic: "He ordered Gui to persuade the city to surrender; Gui refused and died." },
  { zh: "檜，虯之弟也。", literal: "Gui was Chiu's younger brother.", idiomatic: "Gui was Liu Chiu's younger brother." },
  { zh: "太師泰遣王雄與驃騎大將軍武川宇文虯討之。", literal: "Grand Preceptor Tai sent Wang Xiong and Rapid-as-Tiger Grand General Yuwen Chiu of Wuchuan to suppress them.", idiomatic: "Grand preceptor Yuwen Tai sent Wang Xiong and rapid-as-tiger grand general Yuwen Chiu of Wuchuan to suppress them." },
  { zh: "武陵王紀舉兵由外水東下，以永豐侯手為為益州刺史，守成都，使其子宜都王圓肅副之。", literal: "Prince Ji of Wuling raised troops and marched east down the outer waterways, made Marquis Shouwei of Yifeng Inspector of Yizhou to hold Chengdu, and sent his son Prince Yuansu of Yidu as deputy.", idiomatic: "Prince Xiao Ji of Wuling raised troops and marched east down the outer waterways, made Marquis Shouwei of Yifeng inspector of Yizhou to hold Chengdu, and sent his son Prince Yuansu of Yidu as deputy." },
  { zh: "九月，甲戌，司空南平王恪卒。", literal: "In the ninth month, on jiaxu, Minister of Works Prince Ke of Nanping died.", idiomatic: "In the ninth month, on jiaxu, minister of works Prince Xiao Ke of Nanping died." },
  { zh: "甲申，以王僧辯為揚州刺史。", literal: "On jiashen, Wang Senbian was made Inspector of Yangzhou.", idiomatic: "On jiashen, Wang Senbian was made inspector of Yangzhou." },
  { zh: "齊主使告王僧辯、陳霸先曰：「請釋廣陵之圍，必歸廣陵、歷陽兩城。", literal: "The Qi ruler sent word to Wang Senbian and Chen Baxian: \"Please lift the siege of Guangling—we will certainly return Guangling and Liyang.", idiomatic: "The Qi ruler sent word to Wang Senbian and Chen Baxian: \"Please lift the siege of Guangling—we will certainly return Guangling and Liyang.\"" },
  { zh: "」霸先引兵還京口，江北之民從霸先濟江者萬餘口。", literal: "\" Baxian withdrew to Jingkou; more than ten thousand households north of the Yangtze followed Baxian across the river.", idiomatic: "\" Baxian withdrew to Jingkou; more than ten thousand households north of the Yangtze followed Baxian across the river." },
  { zh: "湘東王以霸先為征北大將軍、開府儀同三司、南徐州刺史，征霸先世子昌及兄子頊詣江陵，以昌為員外散騎常侍，頊為領直。", literal: "The Prince of Xiangdong made Baxian Grand General Who Conquers the North, equal in honor to the three dukes with an open office, and Inspector of Southern Xuzhou; he summoned Baxian's heir Chang and nephew Shuo to Jiangling, making Chang supernumerary cavalier attendant and Shuo commander of the palace guard.", idiomatic: "Prince Xiao Yi made Baxian grand general who conquers the north, equal in honor to the three dukes with an open office, and inspector of Southern Xuzhou; he summoned Baxian's heir Chang and nephew Shuo to Jiangling, making Chang supernumerary cavalier attendant and Shuo commander of the palace guard." },
  { zh: "宜豐侯循之降魏也，丞相泰許其南還，久而未遣，從容問劉璠曰：「我於古誰比？", literal: "When Marquis Xun of Yifeng surrendered to Wei, Chancellor Tai had promised he might return south, but long did not send him; at ease he asked Liu Fan, \"Whom among the ancients am I like?", idiomatic: "When Marquis Xiao Xun of Yifeng surrendered to Western Wei, Chancellor Yuwen Tai had promised he might return south, but long did not send him; at ease he asked Liu Fan, \"Whom among the ancients am I like?\"" },
  { zh: "」對曰：「璠常以公為湯、武，今日所見，曾桓、文之不如！", literal: "\" He answered, \"Fan always took you for Tang and Wu; what I see today falls short even of Duke Huan and Duke Wen of Jin!", idiomatic: "\" He answered, \"Fan always took you for Tang and Wu; what I see today falls short even of Duke Huan and Duke Wen of Jin!\"" },
  { zh: "」泰曰：「我安敢比湯、武，庶幾望伊、周，何至不如桓、文！", literal: "\" Tai said, \"How would I dare compare myself to Tang and Wu? I hoped at most for Yi Yin and the Duke of Zhou—how could I be worse than Huan and Wen!", idiomatic: "\" Tai said, \"How would I dare compare myself to Tang and Wu? I hoped at most for Yi Yin and the Duke of Zhou—how could I be worse than Huan and Wen!\"" },
  { zh: "」對曰：「齊桓存三亡國，晉文不失信於伐原。", literal: "\" He answered, \"Duke Huan of Qi preserved three perished states; Duke Wen of Jin did not break faith over the campaign at Yuan.", idiomatic: "\" He answered, \"Duke Huan of Qi preserved three perished states; Duke Wen of Jin did not break faith over the campaign at Yuan.\"" },
  { zh: "」語未竟，泰撫掌曰：「我解爾意，欲激我耳。", literal: "\" Before he finished, Tai clapped his hands and said, \"I understand your meaning—you mean to stir me.", idiomatic: "\" Before he finished, Tai clapped his hands and said, \"I understand your meaning—you mean to stir me.\"" },
  { zh: "」乃謂循曰：「王欲之荊，為之益？", literal: "\" He then said to Xun, \"Do you wish to go to Jing? Shall I help you?", idiomatic: "\" He then said to Xun, \"Do you wish to go to Jing? Shall I help you?\"" },
  { zh: "」循請還江陵，泰厚禮遣之。", literal: "\" Xun asked to return to Jiangling; Tai sent him off with generous rites.", idiomatic: "\" Xun asked to return to Jiangling; Tai sent him off with generous rites." },
  { zh: "循以文武千家自隨，湘東王疑之，遣使覘察，相望於道；", literal: "Xun brought more than a thousand civil and military households with him; the Prince of Xiangdong was suspicious and sent agents to watch, meeting one another all along the road;", idiomatic: "Xun brought more than a thousand civil and military households with him; Prince Xiao Yi was suspicious and sent agents to watch, meeting one another all along the road;" },
  { zh: "始至之夕，命劫竊其財，及旦，循啟輸馬仗，王乃安之，引入，對泣，以循為侍中、驃騎將軍、開府儀同三司。", literal: "on the evening he first arrived, the prince ordered his goods robbed; at dawn Xun reported offering horses and arms, and the prince then was reassured, received him in, wept face to face, and made Xun Attendant-in-Ordinary, Rapid-as-Tiger General, and equal in honor to the three dukes with an open office.", idiomatic: "on the evening he first arrived, the prince ordered his goods robbed; at dawn Xun reported offering horses and arms, and the prince then was reassured, received him in, wept face to face, and made Xun attendant-in-ordinary, rapid-as-tiger general, and equal in honor to the three dukes with an open office." },
  { zh: "冬，十月，齊主自晉陽如離石，自黃櫨嶺起長城，北至社平戍，四百餘里，置三十六戍。", literal: "In winter, the tenth month, the Qi ruler went from Jinyang to Lishi, raised the Long Wall from Huanglu Ridge north to Sheping Garrison—more than four hundred li—and set thirty-six garrisons.", idiomatic: "In winter, the tenth month, the Qi ruler went from Jinyang to Lishi, raised the Long Wall from Huanglu Ridge north to Sheping Garrison—more than four hundred li—and set thirty-six garrisons." },
  { zh: "戊申，湘東王執湘州刺史王琳於殿中，殺其副將殷晏。", literal: "On wushen, the Prince of Xiangdong seized Xiangzhou Inspector Wang Lin in the hall and killed his deputy Yin Yan.", idiomatic: "On wushen, Prince Xiao Yi seized Xiangzhou inspector Wang Lin in the hall and killed his deputy Yin Yan." },
  { zh: "琳本會稽兵家，其姊妹皆入王宮，故琳少在王左右。", literal: "Lin came from a military family in Kuaiji; his sisters had all entered the prince's palace, so Lin grew up at the prince's side.", idiomatic: "Lin came from a military family in Kuaiji; his sisters had all entered the prince's palace, so Lin grew up at the prince's side." },
  { zh: "琳好勇，王以為將帥。", literal: "Lin loved valor; the prince made him a commander.", idiomatic: "Lin loved valor; the prince made him a commander." },
  { zh: "琳傾身下士，所得賞賜，不以入家。", literal: "Lin poured himself out to honor men below him and did not bring rewards home.", idiomatic: "Lin poured himself out to honor men below him and did not bring rewards home." },
  { zh: "麾下萬人，多江、淮群盜，從王僧辯平侯景，與杜龕功居第一。", literal: "Under him were ten thousand men, mostly river-bandits of the Jianghuai; following Wang Senbian he pacified Hou Jing, and with Du Kan his merit ranked first.", idiomatic: "Under him were ten thousand men, mostly river-bandits of the Jianghuai; following Wang Senbian he pacified Hou Jing, and with Du Kan his merit ranked first." },
  { zh: "在建康，恃寵縱暴，僧辯不能禁。", literal: "At Jiankang he relied on favor and ran wild; Senbian could not restrain him.", idiomatic: "At Jiankang he relied on favor and ran wild; Senbian could not restrain him." },
  { zh: "僧辯以宮殿之燒，恐得罪，欲以琳塞責，乃密啟王，請誅琳。", literal: "Senbian, fearing blame for the burning of the palaces, wished to lay the fault on Lin and secretly reported to the prince, asking that Lin be executed.", idiomatic: "Senbian, fearing blame for the burning of the palaces, wished to lay the fault on Lin and secretly reported to the prince, asking that Lin be executed." },
  { zh: "王以琳為湘州，琳自疑及禍，使長史陸納帥部曲赴湘州，身詣江陵陳謝，謂納等曰：「吾若不返，子將安之？", literal: "The prince sent Lin to Xiangzhou; Lin suspected disaster, had Chief Clerk Lu Na lead his household troops to Xiangzhou, and went himself to Jiangling to explain, saying to Na and the rest, \"If I do not return, where will you go?", idiomatic: "The prince sent Lin to Xiangzhou; Lin suspected disaster, had chief clerk Lu Na lead his household troops to Xiangzhou, and went himself to Jiangling to explain, saying to Na and the rest, \"If I do not return, where will you go?\"" },
  { zh: "」鹹曰：「請死之。", literal: "\" All said, \"We ask to die with you.", idiomatic: "\" All said, \"We ask to die with you.\"" },
  { zh: "」相泣而別。", literal: "\" They wept and parted.", idiomatic: "\" They wept and parted." },
  { zh: "至江陵，王下琳吏。", literal: "When he reached Jiangling, the prince handed Lin over to the law officers.", idiomatic: "When he reached Jiangling, the prince handed Lin over to the law officers." },
  { zh: "辛酉，以王子方略為湘州刺史，又以廷尉黃羅漢為長史，使與太舟卿張載至巴陵，先據琳軍。", literal: "On xinyou, Prince Zilüe was made Inspector of Xiangzhou, and Director of Justice Huang Luohan was made chief clerk; they were sent with Grand Master of Boats Zhang Zai to Baling to seize Lin's army first.", idiomatic: "On xinyou, Prince Zilüe was made inspector of Xiangzhou, and director of justice Huang Luohan was made chief clerk; they were sent with grand master of boats Zhang Zai to Baling to seize Lin's army first." },
  { zh: "載有寵於王，而御下峻刻，荊州人疾之如仇。", literal: "Zai had the prince's favor but ruled subordinates harshly; the people of Jingzhou hated him as an enemy.", idiomatic: "Zai had the prince's favor but ruled subordinates harshly; the people of Jingzhou hated him as an enemy." },
  { zh: "羅漢等至琳軍，陸納及士卒並哭，不肯受命，執羅漢及載。", literal: "When Luohan and the rest reached Lin's army, Lu Na and the soldiers all wept, refused to accept orders, and seized Luohan and Zai.", idiomatic: "When Luohan and the rest reached Lin's army, Lu Na and the soldiers all wept, refused to accept orders, and seized Luohan and Zai." },
  { zh: "王遣宦者陳旻往諭之，納對旻刳載腹，抽腸以繫馬足，使繞而走，腸盡氣絕。", literal: "The prince sent eunuch Chen Min to instruct them; Na answered Min by cutting open Zai's belly, drawing out the intestines to tie to a horse's hoof, and making him run in a circle until the guts were gone and breath ended.", idiomatic: "The prince sent eunuch Chen Min to instruct them; Na answered Min by cutting open Zai's belly, drawing out the intestines to tie to a horse's hoof, and making him run in a circle until the guts were gone and breath ended." },
  { zh: "又臠割，出其心，向之抃舞，焚其餘骨。", literal: "He then carved the flesh, took out the heart, danced toward it in triumph, and burned the remaining bones.", idiomatic: "He then carved the flesh, took out the heart, danced toward it in triumph, and burned the remaining bones." },
  { zh: "以黃羅漢清謹而免之。", literal: "Huang Luohan was spared for his purity and care.", idiomatic: "Huang Luohan was spared for his purity and care." },
  { zh: "納與諸將引兵襲湘州，時州中無主，納遂據之。", literal: "Na and the generals led troops to strike Xiangzhou; the province had no leader, and Na seized it.", idiomatic: "Na and the generals led troops to strike Xiangzhou; the province had no leader, and Na seized it." },
  { zh: "公卿籓鎮數勸進於湘東王，十一月，丙子，世祖即皇帝位於江陵，改元，大赦。", literal: "High ministers and frontier lords repeatedly urged the Prince of Xiangdong to ascend; in the eleventh month, on bingzi, Shizu took the throne at Jiangling, changed the era name, and proclaimed a general amnesty.", idiomatic: "High ministers and frontier lords repeatedly urged Prince Xiao Yi to ascend; in the eleventh month, on bingzi, Emperor Yuan took the throne at Jiangling, changed the era name, and proclaimed a general amnesty." },
  { zh: "是日，帝不升正殿，公卿陪列而已。", literal: "That day the emperor did not ascend the main hall; the ministers stood in attendance only.", idiomatic: "That day the emperor did not ascend the main hall; the ministers stood in attendance only." },
  { zh: "丁丑，以宜豐侯循為湘州刺史。", literal: "On dingchou, Marquis Xun of Yifeng was made Inspector of Xiangzhou.", idiomatic: "On dingchou, Marquis Xiao Xun of Yifeng was made inspector of Xiangzhou." },
  { zh: "己卯，立王太子方矩為皇太子，更名元良。", literal: "On jimao, crown prince Fangju was installed as heir apparent and renamed Yuanliang.", idiomatic: "On jimao, crown prince Fangju was installed as heir apparent and renamed Yuanliang." },
  { zh: "皇子方智為晉安王，方略為始安王，方等之子莊為永嘉王。", literal: "The prince's son Fangzhi was made Prince of Jin'an, Zilüe Prince of Shi'an, and Zhuang son of Fangdeng Prince of Yongjia.", idiomatic: "The prince's son Fangzhi was made Prince of Jin'an, Zilüe Prince of Shi'an, and Zhuang son of Fangdeng Prince of Yongjia." },
  { zh: "追尊母阮修容為文宣皇后。", literal: "His mother Lady Ruan Xiurong was posthumously honored as Empress Wenxuan.", idiomatic: "His mother Lady Ruan Xiurong was posthumously honored as Empress Wenxuan." },
  { zh: "侯景之亂，州郡太半入魏，自巴陵以下至建康，以長江為限，荊州界北盡武寧，西拒硤口，嶺南復為蕭勃所據，詔令所行，千里而近，民戶著籍者，不盈三萬而已。", literal: "In Hou Jing's rebellion, more than half the provinces and commanderies fell to Wei; from Baling down to Jiankang the Yangtze was the border; Jingzhou's north ran to Wuning and west to Xiakou; Lingnan was again held by Xiao Bo; imperial orders ran only a thousand li or so, and registered households did not exceed thirty thousand.", idiomatic: "In Hou Jing's rebellion, more than half the provinces and commanderies fell to Western Wei; from Baling down to Jiankang the Yangtze was the border; Jingzhou's north ran to Wuning and west to Xiakou; Lingnan was again held by Xiao Bo; imperial orders ran only a thousand li or so, and registered households did not exceed thirty thousand." },
  { zh: "陸納襲擊衡州刺史丁道貴於淥口，破之。", literal: "Lu Na attacked Hengzhou Inspector Ding Daogui at Lukou and defeated him.", idiomatic: "Lu Na attacked Hengzhou inspector Ding Daogui at Lukou and defeated him." },
  { zh: "道貴奔零陵，其眾悉降於納。", literal: "Daogui fled to Lingling; his troops all surrendered to Na.", idiomatic: "Daogui fled to Lingling; his troops all surrendered to Na." },
  { zh: "上聞之，遣使征司徒王僧辯、右衛將軍杜崱、平北將軍裴之橫與宜豐侯循共討納，循軍巴陵以待之。", literal: "When the emperor heard, he sent orders summoning Minister of Education Wang Senbian, Right Guard General Du Ya, and General Who Pacifies the North Pei Zhiheng with Marquis Xun of Yifeng to suppress Na together; Xun encamped at Baling to await them.", idiomatic: "When the emperor heard, he sent orders summoning minister of education Wang Senbian, right guard general Du Ya, and general who pacifies the north Pei Zhiheng with Marquis Xiao Xun of Yifeng to suppress Na together; Xun encamped at Baling to await them." },
  { zh: "侯景之亂，零陵人李洪雅據其郡，上即以為營州刺史。", literal: "In Hou Jing's rebellion, Li Hongya of Lingling held his commandery; the emperor at once made him Inspector of Yingzhou.", idiomatic: "In Hou Jing's rebellion, Li Hongya of Lingling held his commandery; the emperor at once made him inspector of Yingzhou." },
  { zh: "洪雅請討陸納，上許之。", literal: "Hongya asked to attack Lu Na; the emperor consented.", idiomatic: "Hongya asked to attack Lu Na; the emperor consented." },
  { zh: "丁道貴收餘眾與之俱。", literal: "Ding Daogui gathered his remnant and went with him.", idiomatic: "Ding Daogui gathered his remnant and went with him." },
  { zh: "納遣其將吳藏襲擊，破之，洪雅等退保空雲城，藏引兵圍之。", literal: "Na sent his general Wu Zang to strike, defeated them, and Hongya and the rest withdrew to hold Kongyun; Zang led troops to besiege it.", idiomatic: "Na sent his general Wu Zang to strike, defeated them, and Hongya and the rest withdrew to hold Kongyun; Zang led troops to besiege it." },
  { zh: "頃之，納請降，求送妻子，上遣陳旻至納所，納眾皆泣，曰：「王郎被囚，故我曹旻逃罪於湘州，非有它志也。", literal: "Soon Na asked to surrender and begged to send wife and children; the emperor sent Chen Min to Na's camp; Na's men all wept and said, \"Lord Wang is imprisoned—so we came to Xiangzhou only to escape punishment, with no other intent.", idiomatic: "Soon Na asked to surrender and begged to send wife and children; the emperor sent Chen Min to Na's camp; Na's men all wept and said, \"Lord Wang is imprisoned—we came to Xiangzhou only to escape punishment, with no other intent.\"" },
  { zh: "」乃出妻子付旻。", literal: "\" They then sent out wife and children to Min.", idiomatic: "\" They then sent out wife and children to Min." },
  { zh: "旻至巴陵，循曰：「此詐也，必將襲我。", literal: "When Min reached Baling, Xun said, \"This is a trick—they will surely strike us.", idiomatic: "When Min reached Baling, Xun said, \"This is a trick—they will surely strike us.\"" },
  { zh: "」乃密為之備。", literal: "\" He secretly made preparations.", idiomatic: "\" He secretly made preparations." },
  { zh: "納果夜以輕兵繼旻後，約至城下鼓噪。", literal: "Na indeed sent light troops by night to follow Min, planning to reach the walls and raise a clamor.", idiomatic: "Na indeed sent light troops by night to follow Min, planning to reach the walls and raise a clamor." },
  { zh: "十二月，壬午晨，去巴陵十里，眾謂已至，即鼓噪，軍中皆驚。", literal: "In the twelfth month, on the morning of renwu, ten li from Baling, his men thought they had arrived and at once raised a clamor; the whole army was alarmed.", idiomatic: "In the twelfth month, on the morning of renwu, ten li from Baling, his men thought they had arrived and at once raised a clamor; the whole army was alarmed." },
  { zh: "循坐胡床，於壘門望之，納乘水來攻，矢下如雨，循方食甘蔗，略無懼色。", literal: "Xun sat on a camp stool at the gate of the rampart watching; Na came by water to attack, arrows fell like rain, yet Xun was eating sugarcane with hardly a sign of fear.", idiomatic: "Xun sat on a camp stool at the gate of the rampart watching; Na came by water to attack, arrows fell like rain, yet Xun was eating sugarcane with hardly a sign of fear." },
  { zh: "徐部分將士擊之，獲其一艦。", literal: "Leisurely he deployed officers and soldiers to strike and captured one of their ships.", idiomatic: "Leisurely he deployed officers and soldiers to strike and captured one of their ships." },
  { zh: "納退保長沙。", literal: "Na withdrew to hold Changsha.", idiomatic: "Na withdrew to hold Changsha." },
  { zh: "壬午，齊主還鄴；", literal: "On renwu, the Qi ruler returned to Ye;", idiomatic: "On renwu, the Qi ruler returned to Ye;" },
  { zh: "戊午，復如晉陽。", literal: "on wuwu, he went again to Jinyang.", idiomatic: "on wuwu, he went again to Jinyang." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
